/* Secondary views and interactive states */
.view-heading{display:flex;justify-content:space-between;align-items:flex-start;margin:0 0 20px}.page-section{margin:18px 0}.subject-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.subject-card{padding:17px}.subject-card-head{display:flex;align-items:center;gap:11px}.subject-symbol{width:37px;height:37px;border-radius:11px;display:grid;place-items:center;font-size:17px}.subject-card h3{margin:0;font:700 13px Manrope,sans-serif}.subject-card small{display:block;color:#9aa2b2;font-size:10px;margin-top:3px}.subject-card .subject-score{margin-left:auto;font-weight:700;color:#5d6be6;font-size:12px}.subject-card .progress-line{margin:15px 0 9px}.subject-card-foot{display:flex;justify-content:space-between;color:#929bad;font-size:9px}.topic-list{display:grid;gap:8px;margin-top:15px}.topic-item{border-top:1px solid #f0f1f5;padding:10px 0 0;display:flex;align-items:center;gap:9px}.topic-status{width:17px;height:17px;border-radius:50%;border:1.5px solid #dfe2e9;display:grid;place-items:center;font-size:10px;color:white}.topic-status.complete{background:#3bb98e;border-color:#3bb98e}.topic-name{font-size:10px;flex:1}.topic-item .soft-button,.topic-item .secondary-button{padding:6px 8px;font-size:9px}.topic-empty{font-size:10px;color:#a0a8b7;padding-top:10px}.subject-card-actions{display:flex;gap:7px;margin-top:14px}.subject-card-actions button{padding:7px 9px;font-size:9px}.wide-panel{padding:20px}.readiness-detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:17px}.weight-item{border:1px solid #eff0f5;padding:11px;border-radius:9px}.weight-item span{font-size:9px;color:#8892a6;display:block}.weight-item strong{display:block;margin-top:5px;font:700 14px Manrope}.retention-list,.notification-list{display:grid;gap:9px}.retention-item,.notification-item{display:flex;align-items:center;gap:12px;border:1px solid #eff0f5;padding:12px;border-radius:9px}.retention-date{width:39px;height:39px;border-radius:10px;background:#f0f1ff;color:#6371e8;display:grid;place-items:center;font-size:10px;font-weight:700;line-height:1.1;text-align:center}.retention-copy{flex:1}.retention-copy strong,.notification-copy strong{font-size:11px}.retention-copy small,.notification-copy small{display:block;color:#9aa2b2;font-size:9px;margin-top:4px}.badge{display:inline-flex;align-items:center;border-radius:20px;padding:4px 8px;background:#eef0ff;color:#6572df;font-size:9px;font-weight:600}.badge.overdue{background:#fff0eb;color:#dc7e64}.badge.done{background:#e8f8f2;color:#36a881}.analytics-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.analytics-panel{padding:18px}.chart-large{height:190px;margin-top:12px}.chart-large svg{width:100%;height:100%;overflow:visible}.chart-bars{display:flex;align-items:flex-end;gap:10px;height:150px;padding:9px 5px 0;border-bottom:1px solid #eef0f5}.bar-group{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:6px}.bar{width:min(28px,70%);min-height:2px;border-radius:5px 5px 0 0;background:#7581ec}.bar.secondary{background:#a6adef}.bar-label{font-size:9px;color:#9aa2b2}.chart-legend{display:flex;gap:15px;color:#8d96a8;font-size:9px;margin-top:12px}.legend-dot{width:7px;height:7px;border-radius:50%;background:#6876e9;display:inline-block;margin-right:5px}.table{width:100%;border-collapse:collapse;font-size:10px}.table th{text-align:left;color:#99a1b0;font-weight:500;padding:9px 6px;border-bottom:1px solid #eff0f5}.table td{padding:11px 6px;border-bottom:1px solid #f3f4f7;color:#505c74}.table td:first-child{font-weight:600;color:#303d57}.table tr:last-child td{border-bottom:0}.challenge-layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(240px,.7fr);gap:14px}.challenge-card{padding:20px;background:linear-gradient(130deg,#fff,#fbfaff);}.challenge-hero{background:linear-gradient(120deg,#262d70,#6459c5);color:white;border:0;position:relative;overflow:hidden}.challenge-hero:after{content:'✦';position:absolute;font-size:130px;right:13px;top:-35px;color:#ffffff17}.challenge-hero .eyebrow{color:#c6c5fa}.challenge-hero h2{font:800 21px Manrope;margin:0}.challenge-hero p{font-size:11px;color:#dad9f7;max-width:390px;line-height:1.6}.hero-metrics{display:flex;gap:22px;margin-top:17px}.hero-metric strong{display:block;font:700 17px Manrope}.hero-metric small{font-size:9px;color:#d0cff1}.challenge-missions{display:grid;gap:9px;margin-top:14px}.challenge-banner{padding:12px 14px;border:1px solid #eceefa;border-radius:9px;background:#f7f8ff;color:#66718a;font-size:10px;line-height:1.5}.boss-locked{display:flex;align-items:center;justify-content:space-between;padding:15px;border:1px solid #eff0f5;border-radius:9px}.boss-locked strong{font-size:11px}.boss-locked small{display:block;color:#98a0af;font-size:9px;margin-top:4px}.record-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.record-card{padding:16px}.record-icon{font-size:17px}.record-value{font:800 21px Manrope;margin:11px 0 3px}.record-label{font-size:10px;color:#8790a3}.record-extra{font-size:9px;color:#adb3bf;margin-top:8px}.recommendation{padding:13px;border-radius:10px;background:#eef8f3;border:1px solid #e0f0e9;font-size:10px;color:#526c61;line-height:1.6;margin:13px 0}.modal-backdrop{position:fixed;inset:0;background:#111a32a6;display:grid;place-items:center;padding:20px;z-index:20;backdrop-filter:blur(4px)}.modal-backdrop[hidden]{display:none}.modal{width:min(520px,100%);max-height:88vh;overflow:auto;background:white;border-radius:15px;padding:22px;box-shadow:0 22px 70px #111a3240;animation:pop .18s ease-out}@keyframes pop{from{transform:translateY(8px);opacity:.5}to{transform:none;opacity:1}}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:17px}.modal-head h2{font:800 18px Manrope;margin:0}.modal-head p{font-size:10px;color:#929bad;margin:5px 0 0}.close-button{background:#f5f6f9;border:0;width:29px;height:29px;border-radius:8px;color:#75809a;font-size:16px}.form-grid{display:grid;gap:12px}.form-field label{display:block;font-size:10px;font-weight:600;color:#59647c;margin-bottom:6px}.form-field input,.form-field select,.form-field textarea{width:100%;border:1px solid #e5e8ef;background:#fff;border-radius:8px;padding:10px 11px;color:#344059;outline:none;font-size:11px}.form-field input:focus,.form-field select:focus,.form-field textarea:focus{border-color:#8791f1;box-shadow:0 0 0 3px #707eea15}.form-hint{font-size:9px;color:#9ca4b3;margin-top:5px}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.quiz-progress{height:5px;background:#eff0f5;border-radius:6px;margin:12px 0 17px}.quiz-progress span{display:block;height:100%;background:#6573e9;border-radius:6px;transition:width .2s}.quiz-topic{font-size:9px;color:#8b94a7;text-transform:uppercase;letter-spacing:.8px;font-weight:700}.quiz-question{font:700 15px/1.5 Manrope;margin:9px 0 16px}.quiz-options{display:grid;gap:8px}.quiz-option{width:100%;text-align:left;background:white;border:1px solid #e8eaf0;border-radius:9px;padding:11px 12px;color:#48546b;font-size:11px}.quiz-option:hover{border-color:#929bf0;background:#f9f9ff}.quiz-option.selected{border-color:#6976e9;background:#f2f3ff;color:#414fbe}.quiz-results{text-align:center}.result-score{font:800 35px Manrope;color:#5c6ae6;margin:12px 0 3px}.answer-review{text-align:left;border-top:1px solid #eff0f5;margin-top:15px;padding-top:12px}.review-row{padding:9px 0;border-bottom:1px solid #f3f4f7;font-size:10px;line-height:1.5}.review-row strong{display:block;margin-bottom:3px}.review-row small{color:#8e97a8}.result-meta{font-size:10px;color:#929bad}.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,15px);background:#17233c;color:white;border-radius:9px;padding:11px 16px;font-size:11px;box-shadow:0 10px 24px #17233c30;z-index:30;opacity:0;pointer-events:none;transition:.22s}.toast.show{opacity:1;transform:translate(-50%,0)}.small-note{font-size:9px;color:#a1a8b6;line-height:1.5}.spaced{margin-top:14px}.danger-button{border:1px solid #f1d8d2;background:white;color:#d27c69;padding:8px 10px;border-radius:8px;font-size:10px;font-weight:600}.inline-row{display:flex;align-items:center;gap:8px}.inline-row>*{flex:1}.days-label{font-size:9px;color:#9aa2b2}
@media(max-width:1050px){.sidebar{width:218px;flex-basis:218px}.view-container{padding-left:3%;padding-right:3%}.topbar{padding:0 3%}.stats-grid{grid-template-columns:repeat(2,1fr)}.record-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.sidebar{width:62px;flex-basis:62px;padding:17px 8px}.brand{justify-content:center;padding:0;margin-bottom:27px}.brand>span:last-child,.profile-mini>div:not(.avatar),.profile-mini .chevron,.nav-label,.nav-item:not(.active)::after,.nav-item{font-size:0}.profile-mini{padding:8px 5px;justify-content:center;background:transparent;border:0;margin-bottom:18px}.profile-mini .avatar{width:31px;height:31px}.main-nav{gap:6px}.nav-item{justify-content:center;padding:0;height:40px}.nav-icon{font-size:17px;width:auto}.nav-count,.nav-dot,.sidebar-quote,.settings-link,.sidebar-footer{display:none!important}.quest-label{margin-top:16px}.view-container{padding:22px 16px 40px}.topbar{height:58px;padding:0 16px}.date-chip{display:none}.dashboard-grid,.challenge-layout{grid-template-columns:1fr}.welcome-row{gap:10px}.welcome-row .primary-button{padding:9px;font-size:0}.welcome-row .primary-button .button-icon{font-size:16px}.page-title{font-size:22px}.subject-grid,.analytics-grid{grid-template-columns:1fr}.readiness-detail-grid{grid-template-columns:repeat(2,1fr)}.app-footer{padding-left:16px;padding-right:16px}.app-footer span:last-child{display:none}.top-actions{gap:10px}}@media(max-width:420px){.stats-grid{gap:8px}.stat-card{padding:12px;min-height:97px}.stat-meta{position:static;margin-top:6px}.stat-value{font-size:20px}.view-container{padding-left:12px;padding-right:12px}.readiness-row{grid-template-columns:80px 1fr 27px}.hero-metrics{gap:12px}.panel{padding:14px}}

const STORAGE_KEY = 'study-quest-save-v1';
const DAY = 86400000;
const curriculum = [
  {name:'Biology',icon:'❋',color:'mint',topics:[
    {name:'Cell structure',questions:[['Which organelle produces most ATP?',['Ribosome','Mitochondrion','Golgi apparatus','Nucleus'],1,'Mitochondria generate most cellular ATP through aerobic respiration.'],['What controls what enters and leaves a cell?',['Cell membrane','Cell wall','Cytoplasm','Vacuole'],0,'The selectively permeable cell membrane regulates movement into and out of the cell.'],['Where are proteins assembled?',['Lysosome','Ribosome','Chloroplast','Nucleolus'],1,'Ribosomes translate mRNA into polypeptide chains.'],['Which structure contains most genetic information?',['Nucleus','Vacuole','Cell wall','Golgi apparatus'],0,'In eukaryotes, DNA is primarily stored in the nucleus.']]},
    {name:'Genetics & inheritance',questions:[['What is an allele?',['A form of a gene','A type of cell','A chromosome pair','A protein'],0,'Alleles are alternative versions of the same gene.'],['How many chromosomes are in a typical human body cell?',['23','46','44','92'],1,'Most human somatic cells have 46 chromosomes arranged in 23 pairs.'],['A recessive trait is expressed when…',['One dominant allele is present','Two recessive alleles are present','No genes are present','The trait is acquired'],1,'A recessive phenotype typically appears when both inherited alleles are recessive.'],['Which molecule carries genetic instructions?',['ATP','DNA','Glucose','Lipid'],1,'DNA stores hereditary information in its nucleotide sequence.']]},
    {name:'Ecology & ecosystems',questions:[['A producer gets energy primarily from…',['Other animals','Sunlight','Decomposition','Minerals'],1,'Most ecosystems begin with producers that capture sunlight by photosynthesis.'],['What happens to available energy up a food chain?',['It increases','It stays equal','It decreases','It becomes matter'],2,'Energy is lost at each trophic transfer, often as heat and metabolism.'],['What is a population?',['All species in a biome','One species in an area','All nonliving factors','A food web'],1,'A population is a group of the same species living in a defined area.'],['Which is an abiotic factor?',['Fungi','Predator','Temperature','Grass'],2,'Abiotic factors are nonliving environmental conditions such as temperature.']]},
    {name:'Human body systems',questions:[['Which blood cells carry oxygen?',['Platelets','Red blood cells','White blood cells','Stem cells'],1,'Hemoglobin in red blood cells binds and transports oxygen.'],['Where does most nutrient absorption occur?',['Stomach','Small intestine','Large intestine','Esophagus'],1,'The small intestine has a large surface area for nutrient absorption.'],['Which system coordinates rapid responses?',['Digestive','Nervous','Skeletal','Endocrine'],1,'The nervous system transmits electrical signals for rapid coordination.'],['What is the functional unit of the kidney?',['Neuron','Alveolus','Nephron','Villus'],2,'Nephrons filter blood and regulate water and solute balance.']]}
  ]},
  {name:'Mathematics',icon:'∑',color:'lav',topics:[
    {name:'Algebraic expressions',questions:[['Simplify 3x + 2x.',['5','5x','6x','x'],1,'Like terms add their coefficients: 3x + 2x = 5x.'],['Expand 2(x + 4).',['2x + 4','x + 8','2x + 8','6x'],2,'Distribute 2 to each term: 2x + 8.'],['If x = 3, what is x² + 1?',['7','9','10','12'],2,'Substitute x = 3: 3² + 1 = 10.'],['What is the coefficient of y in 7y − 2?',['−2','2','7','y'],2,'The coefficient is the number multiplying the variable, which is 7.']]},
    {name:'Linear equations',questions:[['Solve x + 7 = 12.',['3','5','7','19'],1,'Subtract 7 from both sides to get x = 5.'],['Solve 3x = 18.',['6','15','21','54'],0,'Divide both sides by 3: x = 6.'],['If 2x − 4 = 8, x = ?',['2','4','6','12'],2,'Add 4, then divide by 2: 2x = 12, so x = 6.'],['What is the slope of y = 4x + 3?',['3','4','−4','7'],1,'In y = mx + b form, m is the slope; here m = 4.']]},
    {name:'Geometry & measurement',questions:[['Area of a rectangle 5 by 3?',['8','15','16','30'],1,'Rectangle area is length times width: 5 × 3 = 15.'],['A triangle’s angles sum to…',['90°','180°','270°','360°'],1,'The interior angles of every triangle add to 180 degrees.'],['Circumference of radius r?',['πr²','2πr','πd²','r/2'],1,'Circumference is 2πr (equivalently πd).'],['A right angle measures…',['45°','90°','180°','360°'],1,'A right angle is exactly 90 degrees.']]},
    {name:'Fractions & percentages',questions:[['What is 1/2 as a percentage?',['25%','50%','75%','100%'],1,'One half is 0.5, or 50 percent.'],['3/4 + 1/4 = ?',['1/2','1','4/8','3/8'],1,'The denominators match, so add numerators: 4/4 = 1.'],['20% of 80 is…',['8','12','16','20'],2,'0.20 × 80 = 16.'],['Simplify 6/9.',['2/3','3/2','1/3','2/9'],0,'Divide numerator and denominator by 3 to get 2/3.']]}
  ]},
  {name:'World History',icon:'◷',color:'peach',topics:[
    {name:'Ancient civilizations',questions:[['Which river was central to ancient Egyptian life?',['Tigris','Nile','Indus','Yellow River'],1,'The Nile provided water, fertile soil, and transport for ancient Egypt.'],['The city-state of Athens is associated with early…',['Democracy','Feudalism','Communism','Monarchy only'],0,'Athens developed an early, limited form of direct democracy.'],['Cuneiform was first developed by the…',['Romans','Sumerians','Maya','Persians'],1,'Sumerians in Mesopotamia developed cuneiform writing.'],['The Great Wall was built in…',['India','China','Egypt','Greece'],1,'Chinese states built and connected wall sections for defense.']]},
    {name:'Trade & exploration',questions:[['The Silk Roads connected China with…',['The Americas','Mediterranean regions','Australia','Antarctica'],1,'Silk Road networks linked East Asia with Central Asia and Mediterranean markets.'],['A major effect of the printing press was…',['Less literacy','Faster spread of ideas','End of trade','Fewer books'],1,'Movable-type printing made texts cheaper and helped ideas circulate faster.'],['The Columbian Exchange moved organisms between…',['Europe and Asia','Old and New Worlds','Africa and Asia only','Oceans'],1,'It refers to the transfer of crops, animals, people, and disease between hemispheres.'],['A primary source is…',['A modern summary','Evidence from the period','A textbook chapter','An encyclopedia'],1,'Primary sources were created by people or institutions close to the event.']]},
    {name:'Revolutions & reform',questions:[['The French Revolution began in…',['1688','1776','1789','1848'],2,'The French Revolution is conventionally dated from 1789.'],['The Declaration of Independence was adopted in…',['1492','1776','1789','1812'],1,'The Second Continental Congress adopted it on July 4, 1776.'],['Industrialization first accelerated in…',['Britain','Brazil','Japan','Canada'],0,'Britain industrialized first, beginning in the late 18th century.'],['A common goal of reform movements is to…',['Preserve every custom','Change laws or institutions','End education','Stop all trade'],1,'Reform seeks improvement through changes to existing institutions or policies.']]},
    {name:'Modern world',questions:[['The United Nations was founded in…',['1918','1939','1945','1961'],2,'The UN was established in 1945 after World War II.'],['The Cold War was mainly a rivalry between…',['Rome and Carthage','US and USSR','China and India','Spain and France'],1,'The US and Soviet Union led opposing political and military blocs.'],['Decolonization describes…',['Expansion of empires','Colonies gaining independence','Industrial growth','Urbanization'],1,'Decolonization is the process by which colonies became independent states.'],['Which is a useful historical source skill?',['Ignore context','Check authorship and purpose','Use only one account','Assume all sources are neutral'],1,'Evaluating author, audience, purpose, and context helps assess a source.']]}
  ]}
];
const freshState=()=>({version:1,createdAt:Date.now(),targetMinutes:120,xp:0,subjects:curriculum.map((s,i)=>({id:'s'+i,name:s.name,icon:s.icon,color:s.color,topics:s.topics.map((t,j)=>({id:`s${i}t${j}`,name:t.name,completedAt:null}))})),sessions:[],quizzes:[],revisions:[],bossBattles:[],dailyRewards:[],lastBossAt:null,activeTimer:null});
function loadState(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY));if(raw&&raw.version===1&&Array.isArray(raw.subjects))return {...freshState(),...raw,activeTimer:null}}catch{}return freshState()}
let state=loadState();let currentView='dashboard';let timerInterval=null;let activeQuiz=null;let toastTimer;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));updateChrome()}
function todayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateAt(ms){return new Date(ms).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function todaySessions(){return state.sessions.filter(x=>todayKey(new Date(x.endedAt))===todayKey())}
function currentDayMissions(){return [{id:'sessions',title:'Finish 2 study sessions',detail:`${Math.min(2,todaySessions().length)} of 2 sessions recorded`,xp:20,done:todaySessions().length>=2},{id:'revision',title:'Revise one previous topic',detail:state.revisions.some(r=>todayKey(new Date(r.completedAt))===todayKey())?'Revision test completed':'Take a scheduled revision test',xp:20,done:state.revisions.some(r=>todayKey(new Date(r.completedAt))===todayKey())},{id:'quiz',title:'Take a 10-question MCQ test',detail:state.quizzes.some(q=>!q.boss&&q.count>=10&&todayKey(new Date(q.endedAt))===todayKey())?'10-question test completed':'Test yourself on a completed topic',xp:20,done:state.quizzes.some(q=>!q.boss&&q.count>=10&&todayKey(new Date(q.endedAt))===todayKey())}]}
function checkDailyReward(){const missions=currentDayMissions(),key=todayKey();if(missions.every(m=>m.done)&&!state.dailyRewards.includes(key)){state.dailyRewards.push(key);state.xp+=50;save();toast('Daily challenge complete! +50 bonus XP ✨')}}
function subjectTopics(s){return s.topics||[]}
function allBank(subjectId,onlyCompleted=true){const index=Number(subjectId.slice(1));const spec=curriculum[index];const subj=state.subjects.find(s=>s.id===subjectId);if(!spec||!subj)return[];return subj.topics.filter(t=>!onlyCompleted||t.completedAt).flatMap(t=>{const ti=Number(t.id.split('t')[1]);const def=spec.topics[ti];return (def?.questions||[]).map((q,i)=>({subjectId,subject:subj.name,topicId:t.id,topic:t.name,index:i,text:q[0],options:q[1],answer:q[2],explanation:q[3]}))})}
function scoreReadiness(subj){const topics=subj.topics||[],completed=topics.filter(t=>t.completedAt).length;const chapter=topics.length?completed/topics.length:0;const due=topics.filter(t=>t.completedAt),revDone=due.length?due.filter(t=>state.revisions.some(r=>r.topicId===t.id)).length/due.length:0;const qs=state.quizzes.filter(q=>q.subjectId===subj.id&&!q.boss);const performance=qs.length?qs.reduce((a,q)=>a+q.percent,0)/qs.length/100:0;const sessions=state.sessions.filter(s=>s.subjectId===subj.id);const activeDays=new Set(sessions.map(s=>todayKey(new Date(s.endedAt)))).size;const since=Math.max(1,Math.min(14,Math.ceil((Date.now()-state.createdAt)/DAY)));const consistency=Math.min(1,activeDays/Math.min(7,since));return Math.round(chapter*25+revDone*20+performance*35+consistency*20)}
function readinessLabel(n){return n>=90?'Exam Ready':n>=75?'Almost Ready':n>=50?'Preparation Needed':'High Priority'}
function dueRevisions(){const now=Date.now(),out=[];for(const s of state.subjects)for(const t of s.topics){if(!t.completedAt)continue;const offsets=[1,3,7,15,30];for(let i=0;i<offsets.length;i++){const done=state.revisions.some(r=>r.topicId===t.id&&r.stage===i+1);if(done)continue;const dueAt=t.completedAt+offsets[i]*DAY;out.push({subject:s,topic:t,stage:i+1,dueAt,overdue:dueAt<=now});break}}return out.sort((a,b)=>a.dueAt-b.dueAt)}
function bossUnlockAt(){return state.lastBossAt?state.lastBossAt+7*DAY:state.createdAt+7*DAY}
function getStreak(){const days=new Set(state.sessions.map(s=>todayKey(new Date(s.endedAt))));let streak=0;const d=new Date();if(!days.has(todayKey(d)))d.setDate(d.getDate()-1);while(days.has(todayKey(d))){streak++;d.setDate(d.getDate()-1)}return streak}
function updateChrome(){if(!state)return;$('#side-level').textContent=String(1+Math.floor(state.xp/250));$('#subject-count').textContent=String(state.subjects.length);$('#revision-dot').style.display=dueRevisions().some(x=>x.overdue)?'block':'none';const alerts=notificationItems();$('#notification-dot').style.display=alerts.length?'block':'none';$('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});if(state.activeTimer){$('#side-level').title='Study timer in progress'}}
function setView(view){currentView=view;$$('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const labels={dashboard:'Overview',subjects:'My subjects',revisions:'Revision queue',analytics:'Analytics',challenges:'Daily challenges',boss:'Boss battle',competition:'Personal records',settings:'Settings & data'};$('#crumb').textContent=labels[view]||'Overview';renderView();window.scrollTo(0,0)}
function renderView(){const v=$('#view-container');const map={dashboard:renderDashboard,subjects:renderSubjects,revisions:renderRevisions,analytics:renderAnalytics,challenges:renderChallenges,boss:renderBoss,competition:renderCompetition,settings:renderSettings};v.innerHTML=(map[currentView]||renderDashboard)();bindView();updateChrome()}
function fmtHours(min){return min>=60?`${(min/60).toFixed(min%60?1:0)}h`:`${Math.round(min)}m`}
function currentTimerText(){if(!state.activeTimer)return '00:00';const secs=Math.max(0,Math.floor((Date.now()-state.activeTimer.startedAt)/1000));return `${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`}
function totalStudyMins(sessions=state.sessions){return sessions.reduce((sum,s)=>sum+s.durationSec/60,0)}
function recentDays(n=7){return Array.from({length:n},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(n-1-i));const k=todayKey(d);const mins=state.sessions.filter(s=>todayKey(new Date(s.endedAt))===k).reduce((a,s)=>a+s.durationSec/60,0);return {date:d,key:k,minutes:mins,label:d.toLocaleDateString(undefined,{weekday:'short'})}})}
function header(title,desc,action=''){return `<div class="view-heading"><div><div class="eyebrow">STUDY QUEST / ${esc(title).toUpperCase()}</div><h1 class="page-title">${esc(title)}</h1><p class="subtitle">${desc}</p></div>${action}</div>`}
function stat(title,value,meta,icon,color,positive=false){return `<article class="stat-card"><div class="stat-top">${title}<span class="stat-icon icon-${color}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-meta ${positive?'positive':''}">${meta}</div></article>`}
function dailyChartSvg(){const days=recentDays(7),max=Math.max(60,...days.map(d=>d.minutes));if(!state.sessions.length)return `<div class="empty-state"><div><span class="empty-emoji">◌</span>Your study trend will appear here after your first recorded session.</div></div>`;const pts=days.map((d,i)=>[30+i*53,84-(d.minutes/max)*56]);const points=pts.map(p=>p.join(',')).join(' ');const area=`30,88 ${points} 348,88`;return `<svg viewBox="0 0 380 112" role="img" aria-label="Daily study time chart"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#6674e9" stop-opacity=".2"/><stop offset="1" stop-color="#6674e9" stop-opacity="0"/></linearGradient></defs><line x1="22" y1="28" x2="365" y2="28" class="chart-gridline"/><line x1="22" y1="56" x2="365" y2="56" class="chart-gridline"/><line x1="22" y1="84" x2="365" y2="84" class="chart-gridline"/><polygon points="${area}" class="chart-area"/><polyline points="${points}" class="chart-line"/>${pts.map(p=>`<circle class="chart-point" cx="${p[0]}" cy="${p[1]}" r="3"/>`).join('')}${days.map((d,i)=>`<text class="chart-label" x="${30+i*53}" y="106" text-anchor="middle">${d.label}</text>`).join('')}</svg>`}

function renderDashboard(){const minsToday=totalStudyMins(todaySessions()),week=totalStudyMins(state.sessions.filter(s=>Date.now()-s.endedAt<7*DAY)),sessionsToday=todaySessions().length,missions=currentDayMissions(),ready=state.subjects.map(s=>({s,n:scoreReadiness(s)}));const due=dueRevisions().filter(x=>x.overdue);const timer=state.activeTimer;const currentSub=timer&&state.subjects.find(s=>s.id===timer.subjectId);const currentTopic=timer&&currentSub?.topics.find(t=>t.id===timer.topicId);const targetPct=Math.min(100,Math.round(minsToday/state.targetMinutes*100));return `<div class="welcome-row"><div><div class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase()}</div><h1 class="page-title">Your next breakthrough starts here.</h1><p class="subtitle">A little progress every day adds up. What will you learn today?</p></div><button class="primary-button" data-action="start-session"><span class="button-icon">＋</span>Start studying</button></div>
<div class="stats-grid">${stat('Study time today',fmtHours(minsToday),`${targetPct}% of ${fmtHours(state.targetMinutes)} daily target`,'◷','lav',targetPct>0)}${stat('Sessions today',String(sessionsToday),sessionsToday?'Recorded sessions':'No sessions recorded yet','◉','mint',sessionsToday>0)}${stat('Total experience',`${state.xp} XP`,`Level ${1+Math.floor(state.xp/250)} · ${state.xp%250}/250 to next`,'✦','peach',true)}${stat('Current streak',`${getStreak()} day${getStreak()===1?'':'s'}`,getStreak()?'Keep your rhythm going':'Start a session to begin','♨','blue',getStreak()>0)}</div>
<div class="dashboard-grid"><div><section class="focus-card"><div class="focus-head"><div class="focus-icon">${timer?'◷':'✦'}</div><div><h3>${timer?'Focus session in progress':'Ready for a focused session?'}</h3><p>${timer?`${esc(currentSub?.name||'Subject')} · ${esc(currentTopic?.name||'Study time')} · timer started ${dateAt(timer.startedAt)}`:'Choose a subject and topic, then log focused study time.'}</p></div></div><div class="focus-actions">${timer?`<span class="timer-label" id="timer-display">${currentTimerText()}</span><button class="primary-button" data-action="stop-session">Finish & save session</button>`:`<button class="primary-button" data-action="start-session"><span class="button-icon">▶</span>Start a session</button><span class="timer-label">Only completed sessions count toward your progress.</span>`}</div></section>
<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Your study rhythm</h2><div class="panel-subtitle">Recorded study time · last 7 days</div></div><button class="text-link" data-view="analytics">Full analytics ↗</button></div><div class="quick-chart">${dailyChartSvg()}</div><div class="streak-row"><span>This week: <strong>${fmtHours(week)}</strong> recorded</span><div class="streak-days">${recentDays(7).map(d=>`<span class="${d.minutes?'filled':''}" title="${d.minutes?fmtHours(d.minutes):'No study recorded'}">${d.label[0]}</span>`).join('')}</div></div></section>
<section class="readiness-card"><div class="panel-heading"><div><h2 class="panel-title">Exam readiness</h2><div class="panel-subtitle">Your preparation, based on actual learning activity</div></div><button class="text-link" data-view="subjects">View subjects ↗</button></div>${ready.length?`<div class="subject-readiness">${ready.map(({s,n})=>`<div class="readiness-row"><span class="readiness-name">${esc(s.name)}</span><div class="readiness-track"><span style="width:${n}%"></span></div><span class="readiness-pct">${n}%</span></div>`).join('')}</div><div class="status-line"><span class="status-bullet"></span>Scores are weighted by chapters, revisions, tests and consistency.</div>`:`<div class="empty-state">Add a subject to start tracking readiness.</div>`}</section></div>
<div><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Daily challenges</h2><div class="panel-subtitle">Reset in ${new Date().toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}) === ''?'':'your local midnight'}</div></div><button class="text-link" data-view="challenges">See all ↗</button></div><div class="challenge-list">${missions.map(m=>`<div class="mission-row ${m.done?'done':''}"><span class="mission-check">${m.done?'✓':''}</span><div class="mission-copy"><strong>${m.title}</strong><small>${m.detail}</small></div><span class="xp-pill">+${m.xp} XP</span></div>`).join('')}</div>${missions.every(m=>m.done)?'<div class="challenge-banner spaced">All missions complete! Your +50 XP completion bonus has been added.</div>':'<div class="challenge-banner spaced">Complete all 3 missions for an extra <strong>50 XP</strong>.</div>'}</section>
<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Up next</h2><div class="panel-subtitle">Your next best steps</div></div></div>${due.length?`<div class="notification-list">${due.slice(0,2).map(r=>`<div class="notification-item"><div class="retention-date">D${r.stage}</div><div class="notification-copy"><strong>${esc(r.topic.name)}</strong><small>${esc(r.subject.name)} · Revision ${r.stage} is due</small></div></div>`).join('')}</div><button class="text-link spaced" data-view="revisions">Open revision queue ↗</button>`:`<div class="empty-state"><div><span class="empty-emoji">✧</span>${state.subjects.some(s=>s.topics.some(t=>t.completedAt))?'No revisions due right now. Keep learning; we’ll remind you when one is scheduled.':'Complete a chapter to schedule your first retention review.'}</div></div>`}</section>
<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Weekly boss battle</h2><div class="panel-subtitle">A focused exam challenge every 7 days</div></div><span class="badge">${Date.now()>=bossUnlockAt()?'UNLOCKED':'LOCKED'}</span></div><div class="challenge-banner">${Date.now()>=bossUnlockAt()?'A new exam challenge is ready when you have completed-topic questions.':'Next battle unlocks '+dateAt(bossUnlockAt())+'. Build your topic library in the meantime.'}</div><button class="text-link spaced" data-view="boss">View boss battle ↗</button></section></div></div>`}
function renderSubjects(){const cards=state.subjects.map(s=>{const topics=s.topics||[],done=topics.filter(t=>t.completedAt).length,n=scoreReadiness(s),sessionCount=state.sessions.filter(x=>x.subjectId===s.id).length;return `<article class="subject-card"><div class="subject-card-head"><div class="subject-symbol icon-${s.color}">${s.icon}</div><div><h3>${esc(s.name)}</h3><small>${done} of ${topics.length} chapters completed</small></div><span class="subject-score">${n}%</span></div><div class="progress-line"><span style="width:${n}%"></span></div><div class="subject-card-foot"><span>${readinessLabel(n)}</span><span>${sessionCount} recorded sessions</span></div><div class="topic-list">${topics.map(t=>`<div class="topic-item"><span class="topic-status ${t.completedAt?'complete':''}">${t.completedAt?'✓':''}</span><span class="topic-name">${esc(t.name)}</span>${t.completedAt?`<button class="soft-button" data-action="quick-revision" data-topic="${t.id}">Review</button>`:`<button class="secondary-button" data-action="complete-topic" data-topic="${t.id}" ${sessionCount?'':'disabled title="Record a study session for this subject first"'}>${sessionCount?'Complete chapter':'Study first'}</button>`}</div>`).join('')}</div><div class="subject-card-actions"><button class="primary-button" data-action="start-session" data-subject="${s.id}"><span class="button-icon">▶</span>Study this subject</button><button class="secondary-button" data-action="subject-quiz" data-subject="${s.id}" ${allBank(s.id).length?'':'disabled'}>Take a test</button></div></article>`}).join('');return `${header('My subjects','Build knowledge chapter by chapter. Completion and readiness update from your recorded learning.') }<div class="subject-grid">${cards}<button class="subject-card add-subject" data-action="add-subject" style="border-style:dashed;box-shadow:none;display:grid;place-items:center;min-height:145px;color:#7a84a1;background:#fbfcff"><span style="font-size:22px;color:#7782ec">＋</span><strong style="font-size:11px">Add a subject</strong><small>Personalize your study space</small></button></div><p class="small-note spaced">Starter subjects include a small practice question bank. They are study materials, not completed progress. Scores and charts only reflect activity you record.</p>`}
function renderRevisions(){const due=dueRevisions(),completed=state.revisions.filter(r=>r.stage>0).sort((a,b)=>b.completedAt-a.completedAt).slice(0,12);return `${header('Knowledge retention','Spaced revision helps move learning into long-term memory. Tests are scheduled 1, 3, 7, 15 and 30 days after chapter completion.')}<section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Scheduled revisions</h2><div class="panel-subtitle">${due.filter(x=>x.overdue).length} due now · ${due.length} upcoming</div></div><span class="badge">${due.length} queued</span></div>${due.length?`<div class="retention-list">${due.map(r=>`<div class="retention-item"><div class="retention-date">DAY<br>${[1,3,7,15,30][r.stage-1]}</div><div class="retention-copy"><strong>${esc(r.topic.name)}</strong><small>${esc(r.subject.name)} · Revision ${r.stage} of 5 · ${r.overdue?'Ready now':'Due '+dateAt(r.dueAt)}</small></div><span class="badge ${r.overdue?'overdue':''}">${r.overdue?'DUE':'UPCOMING'}</span><button class="primary-button" data-action="revision-test" data-topic="${r.topic.id}" data-stage="${r.stage}" ${r.overdue?'':'disabled'}>Take test</button></div>`).join('')}</div>`:`<div class="empty-state"><div><span class="empty-emoji">↻</span>${state.subjects.some(s=>s.topics.some(t=>t.completedAt))?'Your next scheduled revision is still ahead. Check back when it is due.':'Complete a chapter in My subjects to create your first spaced-revision schedule.'}</div></div>`}</section><section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Retention history</h2><div class="panel-subtitle">Recall score from completed revision tests</div></div></div>${completed.length?`<table class="table"><thead><tr><th>Topic</th><th>Revision</th><th>Recall</th><th>Completed</th></tr></thead><tbody>${completed.map(r=>{const topic=findTopic(r.topicId);return `<tr><td>${esc(topic?.topic.name||'Removed topic')}</td><td>Day ${[1,3,7,15,30][r.stage-1]||r.stage}</td><td><strong>${r.percent}%</strong></td><td>${dateAt(r.completedAt)}</td></tr>`}).join('')}</tbody></table>`:`<div class="empty-state">Retention scores appear here after you complete revision tests. No scores have been invented.</div>`}</section>`}
function findTopic(id){for(const s of state.subjects){const t=s.topics.find(x=>x.id===id);if(t)return{subject:s,topic:t}}return null}

function bars(data,max,target=null){const safeMax=Math.max(max||0,target||0,1);return `<div class="chart-bars">${data.map(d=>`<div class="bar-group" title="${esc(d.tip||d.label)}: ${d.minutes!=null?fmtHours(d.minutes):d.value+'%'}"><div class="bar ${d.secondary?'secondary':''}" style="height:${Math.max(2,Math.min(100,(d.value??d.minutes)/safeMax*100))}%"></div><span class="bar-label">${esc(d.label)}</span></div>`).join('')}</div>`}
function renderAnalytics(){const days=recentDays(7),weeks=Array.from({length:6},(_,i)=>{const end=Date.now()-i*7*DAY,start=end-7*DAY;const sess=state.sessions.filter(s=>s.endedAt>start&&s.endedAt<=end);return{label:i?'−'+i+'w':'This wk',value:sess.reduce((a,s)=>a+s.durationSec/60,0),tip:fmtHours(sess.reduce((a,s)=>a+s.durationSec/60,0))}}).reverse();const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));const list=state.quizzes.filter(q=>{const x=new Date(q.endedAt);return x.getFullYear()===d.getFullYear()&&x.getMonth()===d.getMonth()});return{label:d.toLocaleDateString(undefined,{month:'short'}),value:list.length?list.reduce((a,q)=>a+q.percent,0)/list.length:0,tip:list.length?`${list.length} tests · ${Math.round(list.reduce((a,q)=>a+q.percent,0)/list.length)}% avg`:'No tests recorded'}});const subjectScores=state.subjects.map(s=>{const qs=state.quizzes.filter(q=>q.subjectId===s.id&&!q.boss);return{label:s.name.split(' ')[0],value:qs.length?qs.reduce((a,q)=>a+q.percent,0)/qs.length:0,tip:qs.length?`${qs.length} tests · ${Math.round(qs.reduce((a,q)=>a+q.percent,0)/qs.length)}% average`:'No tests recorded'}});const monthQuizzes=state.quizzes.filter(q=>Date.now()-q.endedAt<30*DAY&&!q.boss);return `${header('Performance analytics','Every chart is generated from sessions and tests you have actually recorded. Empty periods remain empty.') }<div class="analytics-grid"><section class="panel analytics-panel"><div class="panel-heading"><div><h2 class="panel-title">Daily study hours</h2><div class="panel-subtitle">Recorded minutes · last 7 days</div></div></div>${state.sessions.length?bars(days.map(d=>({label:d.label,minutes:d.minutes,value:d.minutes,tip:fmtHours(d.minutes)})),Math.max(60,...days.map(d=>d.minutes))):'<div class="empty-state">No recorded study time yet.</div>'}</section><section class="panel analytics-panel"><div class="panel-heading"><div><h2 class="panel-title">Weekly study trends</h2><div class="panel-subtitle">Study minutes · rolling 6 weeks</div></div></div>${state.sessions.length?bars(weeks,Math.max(60,...weeks.map(x=>x.value))):'<div class="empty-state">Weekly trends will appear after sessions are recorded.</div>'}</section><section class="panel analytics-panel"><div class="panel-heading"><div><h2 class="panel-title">Monthly performance</h2><div class="panel-subtitle">Average test accuracy · last 6 months</div></div></div>${state.quizzes.length?bars(months,100):'<div class="empty-state">Complete a test to begin tracking performance.</div>'}</section><section class="panel analytics-panel"><div class="panel-heading"><div><h2 class="panel-title">Subject-wise test scores</h2><div class="panel-subtitle">Average accuracy from completed tests</div></div></div>${state.quizzes.length?bars(subjectScores,100):'<div class="empty-state">No subject scores yet. Test scores are never estimated.</div>'}</section><section class="panel analytics-panel"><div class="panel-heading"><div><h2 class="panel-title">Target vs actual</h2><div class="panel-subtitle">Daily minutes · past 7 days · target ${state.targetMinutes}m</div></div></div>${state.sessions.length?`${bars(days.map(d=>({label:d.label,value:d.minutes,secondary:true,tip:`${Math.round(d.minutes)} recorded minutes vs ${state.targetMinutes} minute target`})),Math.max(state.targetMinutes,...days.map(d=>d.minutes)))}<div class="chart-legend"><span><i class="legend-dot"></i>Actual study</span><span>— Target: ${state.targetMinutes}m/day</span></div>`:'<div class="empty-state">No actual time recorded yet; target comparisons will appear here.</div>'}</section><section class="panel analytics-panel"><div class="panel-heading"><div><h2 class="panel-title">Test score improvement</h2><div class="panel-subtitle">Your latest 7 actual test results</div></div></div>${monthQuizzes.length?bars(monthQuizzes.slice(-7).map((q,i)=>({label:`#${i+1}`,value:q.percent,tip:`${q.subject} · ${q.percent}%`})),100):'<div class="empty-state">Take a test to start your score history.</div>'}</section></div><section class="panel wide-panel spaced"><div class="panel-heading"><div><h2 class="panel-title">Weakness detection & recommended next steps</h2><div class="panel-subtitle">Priorities are inferred from your due revisions, recorded scores and activity.</div></div></div>${renderRecommendations()}</section>`}
function renderRecommendations(){const weak=state.subjects.map(s=>{const qs=state.quizzes.filter(q=>q.subjectId===s.id&&!q.boss);return{s,avg:qs.length?qs.reduce((a,q)=>a+q.percent,0)/qs.length:null}}).filter(x=>x.avg!==null&&x.avg<70).sort((a,b)=>a.avg-b.avg);const due=dueRevisions().filter(x=>x.overdue);const lowTopics=state.subjects.flatMap(s=>s.topics.filter(t=>{const q=state.quizzes.filter(x=>x.topicIds?.includes(t.id));return q.length&&q.reduce((a,x)=>a+x.percent,0)/q.length<60}).map(t=>({s,t})));const last7=recentDays(7),active=last7.filter(d=>d.minutes>0).length;const rec=[];if(due.length)rec.push(`Start with <strong>${esc(due[0].topic.name)}</strong> in ${esc(due[0].subject.name)} — its Day ${due[0].stage} retention test is due.`);if(weak.length)rec.push(`Give <strong>${esc(weak[0].s.name)}</strong> extra practice; your recorded average is ${Math.round(weak[0].avg)}%.`);if(lowTopics.length)rec.push(`Revisit <strong>${esc(lowTopics[0].t.name)}</strong> — recent test answers show this chapter needs reinforcement.`);if(active<4&&state.sessions.length)rec.push(`Your study pattern is uneven: ${active} of the past 7 days have recorded sessions. Try a short, consistent daily block.`);if(!state.sessions.length)rec.push('Start and save a focused study session to build a real baseline. No performance has been inferred yet.');if(!weak.length&&state.quizzes.length)rec.push('No subject average is below 70% yet. Continue testing completed topics to keep your evidence current.');return `<div class="recommendation">${rec.map(x=>`<div>✦ ${x}</div>`).join('')}</div><div class="inline-row"><span class="small-note">Frequently missed MCQ topics are highlighted after you have at least one test result per topic.</span><button class="secondary-button" data-view="revisions">Review due topics</button></div>`}
function renderChallenges(){const missions=currentDayMissions(),done=missions.filter(x=>x.done).length;return `${header('Daily challenges','Three practical missions generated from today’s real activity. Missions reset at local midnight.') }<div class="challenge-layout"><div><section class="challenge-card challenge-hero"><div class="eyebrow">TODAY’S QUEST</div><h2>Make today count.</h2><p>Small, focused actions build consistency. Each mission checks a recorded study or test event — opening the app never earns XP.</p><div class="hero-metrics"><div class="hero-metric"><strong>${done}/3</strong><small>missions complete</small></div><div class="hero-metric"><strong>+${missions.filter(m=>m.done).reduce((a,m)=>a+m.xp,0)} XP</strong><small>mission XP earned</small></div><div class="hero-metric"><strong>+50 XP</strong><small>all-done bonus</small></div></div></section><div class="challenge-missions">${missions.map(m=>`<div class="mission-row ${m.done?'done':''}"><span class="mission-check">${m.done?'✓':''}</span><div class="mission-copy"><strong>${m.title}</strong><small>${m.detail}</small></div><span class="xp-pill">${m.done?'Earned':'+'+m.xp+' XP'}</span>${!m.done?`<button class="secondary-button" data-action="${m.id==='sessions'?'start-session':m.id==='revision'?'daily-revision':'daily-quiz'}">${m.id==='sessions'?'Study':m.id==='revision'?'Revise':'Take test'}</button>`:''}</div>`).join('')}</div></div><div><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Quest rules</h2><div class="panel-subtitle">Fair play, real progress</div></div><span class="stat-icon icon-mint">✓</span></div><div class="challenge-banner">Sessions count only when you finish and save them. Overlapping timers are blocked. Test XP comes from correct answers, and a mission reward can only be claimed once each day.</div><div class="streak-row"><span>Today’s recorded sessions</span><strong>${todaySessions().length}</strong></div><div class="streak-row"><span>Today’s saved tests</span><strong>${state.quizzes.filter(q=>todayKey(new Date(q.endedAt))===todayKey()).length}</strong></div></section><section class="panel"><h2 class="panel-title">Your study goal</h2><p class="panel-subtitle">Current daily target: <strong>${fmtHours(state.targetMinutes)}</strong></p><button class="secondary-button spaced" data-view="settings">Adjust target</button></section></div></div>`}
function renderBoss(){const unlock=bossUnlockAt(),unlocked=Date.now()>=unlock,eligible=state.subjects.filter(s=>allBank(s.id).length),history=state.bossBattles.slice().sort((a,b)=>b.endedAt-a.endedAt);return `${header('Weekly boss battle','An exam-style challenge unlocks every 7 days. Questions only come from chapters you have completed.') }<div class="challenge-layout"><section class="challenge-card challenge-hero"><div class="eyebrow">WEEKLY EXAM CHALLENGE</div><h2>${unlocked?'The arena is open.':'Your next battle is charging.'}</h2><p>${unlocked?eligible.length?'Choose your challenge length and prove what you know.':'Complete a study chapter to unlock question material for the battle.':`Unlocks ${dateAt(unlock)} · ${Math.max(0,Math.ceil((unlock-Date.now())/DAY))} days remaining. Build your topic knowledge first.`}</p><div class="hero-metrics"><div class="hero-metric"><strong>${history.length}</strong><small>battles recorded</small></div><div class="hero-metric"><strong>${history.length?Math.max(...history.map(x=>x.percent))+'%':'—'}</strong><small>personal best</small></div><div class="hero-metric"><strong>${eligible.reduce((a,s)=>a+allBank(s.id).length,0)}</strong><small>available questions</small></div></div><div class="inline-row spaced">${[10,20,30].map(n=>`<button class="primary-button" data-action="start-boss" data-count="${n}" ${(unlocked&&eligible.length)?'':'disabled'}>${n} questions</button>`).join('')}</div><p class="small-note">A battle can sample questions only from completed topics. If your available pool is smaller than the selected length, questions repeat after the full pool has been used.</p></section><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Battle history</h2><div class="panel-subtitle">Your actual results</div></div></div>${history.length?`<div class="notification-list">${history.slice(0,5).map(b=>`<div class="notification-item"><div class="retention-date">${b.percent}%</div><div class="notification-copy"><strong>${b.correct}/${b.count} correct · ${b.xp} XP</strong><small>${dateAt(b.endedAt)} · ${fmtHours(b.durationSec/60)} taken</small></div></div>`).join('')}</div>`:'<div class="empty-state">No battles completed yet. Scores appear here after your first attempt.</div>'}</section></div><section class="panel wide-panel spaced"><div class="panel-heading"><div><h2 class="panel-title">How scoring works</h2><div class="panel-subtitle">Accuracy = correct answers ÷ questions</div></div></div><div class="readiness-detail-grid"><div class="weight-item"><span>Base reward</span><strong>10 XP</strong></div><div class="weight-item"><span>Accuracy bonus</span><strong>+ up to 100 XP</strong></div><div class="weight-item"><span>Marks & accuracy</span><strong>From your answers</strong></div><div class="weight-item"><span>Time taken</span><strong>Measured live</strong></div></div></section>`}

function longestStreak(){const days=[...new Set(state.sessions.map(s=>todayKey(new Date(s.endedAt))))].sort();let best=0,run=0,last=null;for(const k of days){const d=new Date(`${k}T00:00:00`);if(last&&d-last===DAY)run++;else run=1;best=Math.max(best,run);last=d}return best}
function personalBestHours(){const map={};for(const s of state.sessions){const k=todayKey(new Date(s.endedAt));map[k]=(map[k]||0)+s.durationSec/3600}return Math.max(0,...Object.values(map))}
function highestWeeklyXp(){const map={};for(const x of [...state.sessions,...state.quizzes,...state.revisions]){const time=x.endedAt||x.completedAt;if(!time)continue;const d=new Date(time);const wk=`${d.getFullYear()}-${Math.floor((Number(d)-new Date(d.getFullYear(),0,1))/DAY/7)}`;map[wk]=(map[wk]||0)+(x.xp||0)}return Math.max(0,...Object.values(map))}
function mostImproved(){let best=null;for(const s of state.subjects){const qs=state.quizzes.filter(q=>q.subjectId===s.id&&!q.boss&&!q.revision).sort((a,b)=>a.endedAt-b.endedAt);if(qs.length<2)continue;const diff=qs[qs.length-1].percent-qs[0].percent;if(!best||diff>best.diff)best={name:s.name,diff}}return best}
function renderCompetition(){const bestScore=state.quizzes.length?Math.max(...state.quizzes.map(q=>q.percent)):null;const improvement=mostImproved();const records=[['◷',personalBestHours()?`${personalBestHours().toFixed(1)}h`:'—','Personal best study hours','Highest recorded total in one local day'],['◎',bestScore===null?'—':`${bestScore}%`,'Highest test score','Based on completed tests'],['♨',`${longestStreak()} day${longestStreak()===1?'':'s'}`,'Longest study streak','Consecutive days with a saved session'],['✦',`${highestWeeklyXp()} XP`,'Highest weekly XP','Earned from actual saved activity']];return `${header('Personal records','Compete against your own previous records. Only saved sessions, tests and revisions count.') }<div class="record-grid">${records.map((r,i)=>`<article class="record-card"><span class="record-icon icon-${['lav','blue','mint','peach'][i]} stat-icon">${r[0]}</span><div class="record-value">${r[1]}</div><div class="record-label">${r[2]}</div><div class="record-extra">${r[3]}</div></article>`).join('')}</div><section class="panel wide-panel spaced"><div class="panel-heading"><div><h2 class="panel-title">Most improved subject</h2><div class="panel-subtitle">Change from first to latest non-boss test score</div></div></div>${improvement?`<div class="inline-row"><div class="subject-symbol icon-lav">↗</div><div><strong>${esc(improvement.name)}</strong><div class="small-note">${improvement.diff>=0?'+':''}${Math.round(improvement.diff)} percentage points across your actual tests.</div></div><span class="badge">${improvement.diff>=0?'IMPROVING':'NEEDS ATTENTION'}</span></div>`:'<div class="empty-state">Take at least two tests in a subject to compare your actual first and latest scores.</div>'}</section><section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Your scoreboard</h2><div class="panel-subtitle">A snapshot of what you have really achieved</div></div></div><div class="readiness-detail-grid"><div class="weight-item"><span>Recorded sessions</span><strong>${state.sessions.length}</strong></div><div class="weight-item"><span>Total focused time</span><strong>${fmtHours(totalStudyMins())}</strong></div><div class="weight-item"><span>Tests completed</span><strong>${state.quizzes.length}</strong></div><div class="weight-item"><span>Chapters completed</span><strong>${state.subjects.reduce((a,s)=>a+s.topics.filter(t=>t.completedAt).length,0)}</strong></div></div></section>`}
function renderSettings(){return `${header('Settings & data','Set a realistic goal and control the learning data stored on this device.') }<section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Daily study target</h2><div class="panel-subtitle">Used for your target-versus-actual analytics and reminders</div></div></div><form id="target-form" class="inline-row"><div class="form-field"><label for="target-minutes">Minutes per day</label><input id="target-minutes" type="number" min="15" max="720" step="15" value="${state.targetMinutes}" required></div><button class="primary-button" type="submit">Save target</button></form></section><section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Your data</h2><div class="panel-subtitle">Saved locally in this browser. You can export a backup or restore it later.</div></div></div><div class="section-actions"><button class="secondary-button" data-action="export-data">↓ Export backup</button><button class="secondary-button" data-action="import-data">↑ Import backup</button><input id="import-file" type="file" accept="application/json" hidden></div><p class="small-note spaced">No account or server is used. Clearing browser storage removes this local progress. Imported files replace the current progress after validation.</p></section><section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Starter subjects</h2><div class="panel-subtitle">Add your own subject containers. Starter MCQ content is available for Biology, Mathematics and World History.</div></div><button class="secondary-button" data-action="add-subject">＋ Add subject</button></div><p class="small-note">Custom subject chapters are for organizing your own study topics. The built-in MCQ bank is intentionally limited to the three starter subjects; no generated questions or scores are presented as verified knowledge for custom subjects.</p></section><section class="panel wide-panel"><div class="panel-heading"><div><h2 class="panel-title">Reset progress</h2><div class="panel-subtitle">This permanently clears all recorded sessions, scores, XP and custom subjects on this device.</div></div></div><button class="danger-button" data-action="reset-data">Reset all progress</button></section>`}
function notificationItems(){const out=[],mins=totalStudyMins(todaySessions());if(mins<state.targetMinutes)out.push({icon:'◷',title:'Daily study target',detail:`${Math.max(0,Math.ceil(state.targetMinutes-mins))} minutes left to your ${fmtHours(state.targetMinutes)} goal.`,view:'dashboard'});const due=dueRevisions().filter(x=>x.overdue);if(due.length)out.push({icon:'↻',title:'Pending revisions',detail:`${due.length} retention test${due.length===1?'':'s'} ready to take.`,view:'revisions'});const missions=currentDayMissions().filter(x=>!x.done);if(missions.length)out.push({icon:'⚑',title:'Unfinished missions',detail:`${missions.length} daily challenge${missions.length===1?'':'s'} still open.`,view:'challenges'});if(Date.now()>=bossUnlockAt())out.push({icon:'♜',title:'Weekly Boss Battle',detail:'Your weekly exam challenge is unlocked.',view:'boss'});else out.push({icon:'♜',title:'Upcoming Boss Battle',detail:`Unlocks ${dateAt(bossUnlockAt())}.`,view:'boss'});if(state.activeTimer)out.unshift({icon:'◉',title:'Study timer is running',detail:'Finish and save your session when you are done.',view:'dashboard'});return out}
function renderNotifications(){const items=notificationItems();openModal(`<div class="modal-head"><div><h2>Smart reminders</h2><p>Based on your saved activity and schedule.</p></div><button class="close-button" data-action="close-modal">×</button></div><div class="notification-list">${items.map(n=>`<button class="notification-item" style="width:100%;text-align:left;background:#fff" data-view="${n.view}"><span class="stat-icon icon-lav">${n.icon}</span><span class="notification-copy"><strong>${n.title}</strong><small>${n.detail}</small></span><span>›</span></button>`).join('')}</div>${items.length?'':'<div class="empty-state">No reminders right now.</div>'}`)}

