'use strict';
const KEY='study-quest-save-v1', DAY=86400000;
const curriculum=[
 {name:'Biology',icon:'❋',color:'mint',topics:[
  ['Cell structure',[['Which organelle produces most ATP?',['Ribosome','Mitochondrion','Golgi apparatus','Nucleus'],1,'Mitochondria generate most cellular ATP through aerobic respiration.'],['What controls what enters and leaves a cell?',['Cell membrane','Cell wall','Cytoplasm','Vacuole'],0,'The selectively permeable cell membrane regulates movement.'],['Where are proteins assembled?',['Lysosome','Ribosome','Chloroplast','Nucleolus'],1,'Ribosomes translate mRNA into polypeptides.'],['Which structure holds most genetic information?',['Nucleus','Vacuole','Cell wall','Golgi apparatus'],0,'In eukaryotes, DNA is primarily stored in the nucleus.']]],
  ['Genetics & inheritance',[['What is an allele?',['A form of a gene','A type of cell','A chromosome pair','A protein'],0,'Alleles are alternative versions of the same gene.'],['How many chromosomes are in a typical human body cell?',['23','46','44','92'],1,'Most human somatic cells have 46 chromosomes.'],['A recessive trait is expressed when…',['One dominant allele is present','Two recessive alleles are present','No genes are present','The trait is acquired'],1,'A recessive phenotype typically appears with two recessive alleles.'],['Which molecule carries genetic instructions?',['ATP','DNA','Glucose','Lipid'],1,'DNA stores hereditary information.']]],
  ['Ecology & ecosystems',[['A producer gets energy primarily from…',['Other animals','Sunlight','Decomposition','Minerals'],1,'Producers capture sunlight through photosynthesis.'],['Available energy up a food chain generally…',['Increases','Stays equal','Decreases','Becomes matter'],2,'Energy is lost at each trophic transfer.'],['What is a population?',['All species in a biome','One species in an area','All nonliving factors','A food web'],1,'A population is a group of the same species in an area.'],['Which is an abiotic factor?',['Fungi','Predator','Temperature','Grass'],2,'Abiotic factors are nonliving conditions.']]],
  ['Human body systems',[['Which blood cells carry oxygen?',['Platelets','Red blood cells','White blood cells','Stem cells'],1,'Hemoglobin in red blood cells binds oxygen.'],['Where does most nutrient absorption occur?',['Stomach','Small intestine','Large intestine','Esophagus'],1,'The small intestine absorbs most nutrients.'],['Which system coordinates rapid responses?',['Digestive','Nervous','Skeletal','Endocrine'],1,'The nervous system transmits rapid electrical signals.'],['What is the functional unit of the kidney?',['Neuron','Alveolus','Nephron','Villus'],2,'Nephrons filter blood and regulate water and solutes.']]]
 ]},
 {name:'Mathematics',icon:'∑',color:'lav',topics:[
  ['Algebraic expressions',[['Simplify 3x + 2x.',['5','5x','6x','x'],1,'Add like-term coefficients: 3x + 2x = 5x.'],['Expand 2(x + 4).',['2x + 4','x + 8','2x + 8','6x'],2,'Distribute 2 to get 2x + 8.'],['If x = 3, what is x² + 1?',['7','9','10','12'],2,'Substitute: 3² + 1 = 10.'],['What is the coefficient of y in 7y − 2?',['−2','2','7','y'],2,'The coefficient multiplying y is 7.']]],
  ['Linear equations',[['Solve x + 7 = 12.',['3','5','7','19'],1,'Subtract 7 from both sides: x = 5.'],['Solve 3x = 18.',['6','15','21','54'],0,'Divide both sides by 3: x = 6.'],['If 2x − 4 = 8, x = ?',['2','4','6','12'],2,'Add 4, then divide by 2: x = 6.'],['What is the slope of y = 4x + 3?',['3','4','−4','7'],1,'In y = mx + b form, m is the slope.']]],
  ['Geometry & measurement',[['Area of a rectangle 5 by 3?',['8','15','16','30'],1,'Area is length times width: 5 × 3 = 15.'],['A triangle’s angles sum to…',['90°','180°','270°','360°'],1,'Interior angles of a triangle add to 180°.'],['Circumference of radius r?',['πr²','2πr','πd²','r/2'],1,'Circumference is 2πr (or πd).'],['A right angle measures…',['45°','90°','180°','360°'],1,'A right angle is exactly 90°.']]],
  ['Fractions & percentages',[['What is 1/2 as a percentage?',['25%','50%','75%','100%'],1,'One half is 50 percent.'],['3/4 + 1/4 = ?',['1/2','1','4/8','3/8'],1,'4/4 equals 1.'],['20% of 80 is…',['8','12','16','20'],2,'0.20 × 80 = 16.'],['Simplify 6/9.',['2/3','3/2','1/3','2/9'],0,'Divide numerator and denominator by 3.']]]
 ]},
 {name:'World History',icon:'◷',color:'peach',topics:[
  ['Ancient civilizations',[['Which river was central to ancient Egyptian life?',['Tigris','Nile','Indus','Yellow River'],1,'The Nile provided water, fertile soil, and transport.'],['Athens is associated with early…',['Democracy','Feudalism','Communism','Monarchy only'],0,'Athens developed an early form of direct democracy.'],['Cuneiform was first developed by the…',['Romans','Sumerians','Maya','Persians'],1,'Sumerians in Mesopotamia developed cuneiform.'],['The Great Wall was built in…',['India','China','Egypt','Greece'],1,'Chinese states built wall sections for defense.']]],
  ['Trade & exploration',[['The Silk Roads connected China with…',['The Americas','Mediterranean regions','Australia','Antarctica'],1,'Silk Road networks linked East Asia to Mediterranean markets.'],['A major effect of the printing press was…',['Less literacy','Faster spread of ideas','End of trade','Fewer books'],1,'Printing made texts cheaper and ideas spread faster.'],['The Columbian Exchange moved organisms between…',['Europe and Asia','Old and New Worlds','Africa and Asia only','Oceans'],1,'It transferred crops, animals, people, and disease between hemispheres.'],['A primary source is…',['A modern summary','Evidence from the period','A textbook chapter','An encyclopedia'],1,'Primary sources originate close to the event.']]],
  ['Revolutions & reform',[['The French Revolution began in…',['1688','1776','1789','1848'],2,'The French Revolution is conventionally dated from 1789.'],['The Declaration of Independence was adopted in…',['1492','1776','1789','1812'],1,'It was adopted on July 4, 1776.'],['Industrialization first accelerated in…',['Britain','Brazil','Japan','Canada'],0,'Britain industrialized first in the late 18th century.'],['A common goal of reform movements is to…',['Preserve every custom','Change laws or institutions','End education','Stop all trade'],1,'Reform improves existing institutions or policies.']]],
  ['Modern world',[['The United Nations was founded in…',['1918','1939','1945','1961'],2,'The UN was established in 1945.'],['The Cold War was mainly a rivalry between…',['Rome and Carthage','US and USSR','China and India','Spain and France'],1,'The US and Soviet Union led opposing blocs.'],['Decolonization describes…',['Expansion of empires','Colonies gaining independence','Industrial growth','Urbanization'],1,'Decolonization is the process of colonies becoming independent.'],['Which is a useful historical source skill?',['Ignore context','Check authorship and purpose','Use only one account','Assume all sources are neutral'],1,'Authorship, audience, purpose, and context help assess sources.']]]
 ]}
];
function fresh(){return {version:1,createdAt:Date.now(),targetMinutes:120,xp:0,subjects:curriculum.map((s,i)=>({id:'s'+i,name:s.name,icon:s.icon,color:s.color,topics:s.topics.map((t,j)=>({id:`s${i}t${j}`,name:t[0],completedAt:null}))})),sessions:[],quizzes:[],revisions:[],bossBattles:[],dailyRewards:[],lastBossAt:null,activeTimer:null}}
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x?.version===1&&Array.isArray(x.subjects))return {...fresh(),...x,activeTimer:null}}catch{}return fresh()}
let state=load(),view='dashboard',quiz=null,timerTick=null,toastTick=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fmtDate=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const minsText=m=>m>=60?`${(m/60).toFixed(m%60?1:0)}h`:`${Math.round(m)}m`;
function save(){localStorage.setItem(KEY,JSON.stringify(state));chrome()}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTick);toastTick=setTimeout(()=>el.classList.remove('show'),2500)}
function openModal(html){$('#modal').innerHTML=html;$('#modal-backdrop').hidden=false}
function closeModal(){$('#modal-backdrop').hidden=true;$('#modal').innerHTML=''}
function allQs(subjectId,completed=true){const ix=Number(String(subjectId).slice(1)),spec=curriculum[ix],s=state.subjects.find(x=>x.id===subjectId);if(!spec||!s)return[];return s.topics.filter(t=>!completed||t.completedAt).flatMap(t=>{const def=spec.topics[Number(t.id.split('t')[1])];return (def?.[1]||[]).map((q,i)=>({subjectId,subject:s.name,topicId:t.id,topic:t.name,index:i,text:q[0],options:q[1],answer:q[2],explanation:q[3]}))})}
function findTopic(id){for(const s of state.subjects){const t=s.topics.find(x=>x.id===id);if(t)return{s,t}}return null}
function sessionMins(list=state.sessions){return list.reduce((a,x)=>a+x.durationSec/60,0)}
function todaySessions(){return state.sessions.filter(s=>key(new Date(s.endedAt))===key())}
function missions(){const todayQ=state.quizzes.filter(q=>key(new Date(q.endedAt))===key());return [{id:'sessions',title:'Finish 2 study sessions',detail:`${Math.min(2,todaySessions().length)} of 2 sessions recorded`,xp:20,done:todaySessions().length>=2},{id:'revision',title:'Revise one previous topic',detail:state.revisions.some(r=>key(new Date(r.completedAt))===key())?'Revision test completed':'Take a scheduled revision test',xp:20,done:state.revisions.some(r=>key(new Date(r.completedAt))===key())},{id:'quiz',title:'Take a 10-question MCQ test',detail:todayQ.some(q=>!q.boss&&!q.revision&&q.count>=10)?'10-question test completed':'Test yourself on a completed topic',xp:20,done:todayQ.some(q=>!q.boss&&!q.revision&&q.count>=10)}]}
function claimDaily(){const k=key();if(missions().every(x=>x.done)&&!state.dailyRewards.includes(k)){state.dailyRewards.push(k);state.xp+=50;save();toast('Daily challenge complete! +50 bonus XP ✨')}}
function dueList(){const out=[];for(const s of state.subjects)for(const t of s.topics){if(!t.completedAt)continue;for(let i=0;i<5;i++){if(state.revisions.some(r=>r.topicId===t.id&&r.stage===i+1))continue;const due=t.completedAt+[1,3,7,15,30][i]*DAY;out.push({s,t,stage:i+1,due,overdue:due<=Date.now()});break}}return out.sort((a,b)=>a.due-b.due)}
function readiness(s){const ts=s.topics||[],done=ts.filter(t=>t.completedAt),chapter=ts.length?done.length/ts.length:0,rev=done.length?done.filter(t=>state.revisions.some(r=>r.topicId===t.id)).length/done.length:0,qs=state.quizzes.filter(q=>q.subjectId===s.id&&!q.boss),perf=qs.length?qs.reduce((a,q)=>a+q.percent,0)/qs.length/100:0,sessions=state.sessions.filter(x=>x.subjectId===s.id),days=new Set(sessions.map(x=>key(new Date(x.endedAt)))).size,elapsed=Math.max(1,Math.min(14,Math.ceil((Date.now()-state.createdAt)/DAY))),consistency=Math.min(1,days/Math.min(7,elapsed));return Math.round(chapter*25+rev*20+perf*35+consistency*20)}
function status(n){return n>=90?'Exam Ready':n>=75?'Almost Ready':n>=50?'Preparation Needed':'High Priority'}
function bossAt(){return state.lastBossAt?state.lastBossAt+7*DAY:state.createdAt+7*DAY}
function streak(){const ds=new Set(state.sessions.map(x=>key(new Date(x.endedAt))));let d=new Date();if(!ds.has(key(d)))d.setDate(d.getDate()-1);let n=0;while(ds.has(key(d))){n++;d.setDate(d.getDate()-1)}return n}
function days7(){return Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const m=state.sessions.filter(x=>key(new Date(x.endedAt))===key(d)).reduce((a,x)=>a+x.durationSec/60,0);return {d,label:d.toLocaleDateString(undefined,{weekday:'short'}),m}})}
function chrome(){if(!state)return;$('#side-level').textContent=1+Math.floor(state.xp/250);$('#subject-count').textContent=state.subjects.length;$('#revision-dot').style.display=dueList().some(x=>x.overdue)?'block':'none';$('#notification-dot').style.display=reminders().length?'block':'none';$('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function setView(v){view=v;$$('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const labels={dashboard:'Overview',subjects:'My subjects',revisions:'Revision queue',analytics:'Analytics',challenges:'Daily challenges',boss:'Boss battle',competition:'Personal records',settings:'Settings & data'};$('#crumb').textContent=labels[v]||'Overview';render();window.scrollTo(0,0)}
function render(){const f={dashboard:dashboard,subjects:subjects,revisions:revisions,analytics:analytics,challenges:challenges,boss:boss,competition:records,settings:settings};$('#view-container').innerHTML=(f[view]||dashboard)();bind();chrome()}
function header(title,desc,action=''){return `<div class="view-heading"><div><div class="eyebrow">STUDY QUEST / ${esc(title).toUpperCase()}</div><h1 class="page-title">${esc(title)}</h1><p class="subtitle">${desc}</p></div>${action}</div>`}
