function reminders(){const out=[],due=dueList().filter(x=>x.overdue);if(due.length)out.push({title:`${due.length} revision${due.length===1?'':'s'} due`,detail:'A short recall check can strengthen retention.',nav:'revisions'});if(!todaySessions().length)out.push({title:'Your daily streak is waiting',detail:'A focused study session starts today’s progress.',nav:'dashboard'});const goal=state.targetMinutes-sessionMins(todaySessions());if(goal>0&&todaySessions().length)out.push({title:`${minsText(goal)} to your daily goal`,detail:'You are building a steady study rhythm.',nav:'dashboard'});return out}
function settings(){return `${header('Settings & data','Your progress stays in this browser. Export a backup whenever you like.')}<div class="settings-grid"><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR ROUTINE</span><h2>Study goal & reminders</h2></div></div><label class="field-label" for="goal-minutes">Daily study goal (minutes)</label><div class="inline-form"><input id="goal-minutes" type="number" min="15" max="720" step="15" value="${state.targetMinutes}"><button class="primary-button" data-action="save-goal">Save goal</button></div><p class="panel-copy">The goal tracks completed session time only; open tabs and breaks do not count.</p><div class="setting-row"><div><strong>Smart reminders</strong><small>Show gentle in-app reminders for due reviews and today’s goal.</small></div><button class="secondary-button" data-action="reminder-settings">${state.remindersEnabled===false?'Enable reminders':'Reminders on'}</button></div></section><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">PORTABLE PROGRESS</span><h2>Backup & restore</h2></div></div><p class="panel-copy">Export your subjects, session log, test history, XP, and preferences to a JSON file.</p><div class="button-row"><button class="secondary-button" data-action="export">Download backup</button><button class="secondary-button" data-action="import">Import backup</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></section><section class="panel wide-panel danger-panel"><div class="panel-heading"><div><span class="eyebrow">START FRESH</span><h2>Reset your learning data</h2></div></div><p class="panel-copy">This permanently removes local sessions, scores, subjects, and earned XP. Export a backup first if you want to keep them.</p><button class="danger-button" data-action="reset">Reset all progress</button></section></div>`}
function startSessionDialog(){if(state.activeTimer){stopSession();return}openModal(`<div class="modal-head"><div><span class="eyebrow">FOCUS SESSION</span><h2>What are you studying?</h2></div><button class="modal-close" data-action="close-modal">×</button></div><p class="panel-copy">Your timer begins only when you confirm. Complete at least 5 focused minutes to record a session and earn XP.</p><label class="field-label" for="session-subject">Subject</label><select id="session-subject">${state.subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" data-action="confirm-session">Start focus timer</button></div>`)}
function startSession(subjectId){if(state.activeTimer)return toast('A focus timer is already running.');const s=state.subjects.find(x=>x.id===subjectId);if(!s)return;state.activeTimer={subjectId:s.id,subjectName:s.name,startedAt:Date.now()};save();closeModal();render();timerTick=setInterval(()=>{if(!state.activeTimer){clearInterval(timerTick);return}const el=$('#session-clock');if(el)el.textContent=elapsedText(Date.now()-state.activeTimer.startedAt)},1000);toast('Focus timer started. You’ve got this!')}
function elapsedText(ms){const n=Math.floor(ms/1000);return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function stopSession(){const t=state.activeTimer;if(!t)return toast('No session is running.');const seconds=Math.floor((Date.now()-t.startedAt)/1000);if(seconds<300){state.activeTimer=null;save();clearInterval(timerTick);render();toast('Session was under 5 minutes, so it was not recorded.');return}const durationSec=Math.min(seconds,12*3600),xp=Math.min(60,Math.floor(durationSec/300)*5),now=Date.now();state.sessions.push({id:crypto.randomUUID?.()||String(now),subjectId:t.subjectId,subjectName:t.subjectName,startedAt:t.startedAt,endedAt:now,durationSec,xp});state.xp+=xp;state.activeTimer=null;save();clearInterval(timerTick);checkMissions();render();toast(`Session saved · +${xp} XP`)}
function completeTopic(id){const x=findTopic(id);if(!x)return;if(x.t.completedAt)return toast('This topic is already completed.');x.t.completedAt=Date.now();save();render();toast('Topic completed. Spaced reviews are now scheduled!')}
function beginQuiz(type,subjectId,topicId){if(quiz)return toast('Finish or close the current test first.');let pool=[];if(topicId)pool=allQs(findTopic(topicId)?.s.id||'',false).filter(q=>q.topicId===topicId);else if(subjectId)pool=allQs(subjectId,true);else pool=state.subjects.flatMap(s=>allQs(s.id,true));if(!pool.length)return toast('Study a topic first to unlock its questions.');if(type==='revision'&&topicId)pool=pool.filter(q=>q.topicId===topicId);const n=type==='boss'?10:Math.min(10,pool.length);if(type==='boss'&&pool.length<10)return toast('Complete more topics to unlock 10 unique boss questions.');pool.sort(()=>Math.random()-.5);quiz={type,subjectId:subjectId||pool[0].subjectId,topicId,questions:pool.slice(0,n),answers:Array(n).fill(null),index:0,startedAt:Date.now()};renderQuestion()}
function renderQuestion(){if(!quiz)return;const q=quiz.questions[quiz.index];openModal(`<div class="quiz-top"><div><span class="eyebrow">${quiz.type==='boss'?'WEEKLY BOSS':quiz.type==='revision'?'SPACED REVISION':'KNOWLEDGE CHECK'}</span><h2>${esc(q.subject)} · ${esc(q.topic)}</h2></div><button class="modal-close" data-action="quit-quiz">×</button></div><div class="quiz-progress"><span>Question ${quiz.index+1} of ${quiz.questions.length}</span><div class="progress-line"><i style="width:${(quiz.index+1)/quiz.questions.length*100}%"></i></div></div><h3 class="quiz-prompt">${esc(q.text)}</h3><div class="answer-list">${q.options.map((x,i)=>`<button class="answer-option ${quiz.answers[quiz.index]===i?'selected':''}" data-action="answer" data-answer="${i}"><span class="answer-letter">${String.fromCharCode(65+i)}</span>${esc(x)}</button>`).join('')}</div><div class="modal-actions"><span class="quiz-note">Answers are reviewed after submission.</span><button class="primary-button" data-action="quiz-next" ${quiz.answers[quiz.index]===null?'disabled':''}>${quiz.index===quiz.questions.length-1?'Submit test':'Next question →'}</button></div>`)}
function quizNext(){if(!quiz||quiz.answers[quiz.index]===null)return;if(quiz.index<quiz.questions.length-1){quiz.index++;renderQuestion();return}finishQuiz()}
function finishQuiz(){const qz=quiz,correct=qz.questions.reduce((a,q,i)=>a+(q.answer===qz.answers[i]?1:0),0),count=qz.questions.length,percent=Math.round(correct/count*100),now=Date.now(),won=qz.type==='boss'&&percent>=70,xp=Math.max(5,Math.round(correct*4+(percent>=80?10:0)))+(won?100:0),subject=state.subjects.find(s=>s.id===qz.subjectId);const result={id:crypto.randomUUID?.()||String(now),subjectId:qz.subjectId,subjectName:subject?.name||qz.questions[0].subject,topicId:qz.topicId||null,endedAt:now,count,correct,percent,xp,boss:qz.type==='boss',revision:qz.type==='revision',answers:qz.answers,questionIds:qz.questions.map(x=>`${x.topicId}:${x.index}`)};state.quizzes.push(result);state.xp+=xp;if(qz.type==='revision'){const t=findTopic(qz.topicId)?.t;if(t){const stage=dueList().find(x=>x.t.id===t.id)?.stage||1;state.revisions.push({topicId:t.id,stage,completedAt:now,percent,xp:xp})}}if(qz.type==='boss'){state.lastBossAt=now;state.bossBattles.push({endedAt:now,percent,count,correct,xp:won?100:0,won})}quiz=null;save();checkMissions();showResults(result,qz.questions)}
// APP_MORE3

