function showReadiness(id){const s=state.subjects.find(x=>x.id===id);if(!s)return;const done=s.topics.filter(t=>t.completedAt).length,rev=done?s.topics.filter(t=>t.completedAt&&state.revisions.some(r=>r.topicId===t.id)).length/done:0,tests=state.quizzes.filter(q=>q.subjectId===id&&!q.boss),avg=tests.length?Math.round(tests.reduce((a,x)=>a+x.percent,0)/tests.length):0,days=new Set(state.sessions.filter(x=>x.subjectId===id).map(x=>key(new Date(x.endedAt)))).size;openModal(`<div class="modal-head"><div><span class="eyebrow">EXAM READINESS</span><h2>${esc(s.name)} · ${readiness(s)}%</h2></div><button class="modal-close" data-action="close-modal">×</button></div><p class="panel-copy">${status(readiness(s))} — this indicator combines curriculum coverage, actual test performance, spaced revision, and session consistency. It is a guide, not an exam prediction.</p><div class="readiness-detail-grid">${[['Coverage',`${done}/${s.topics.length} topics`,25],['Test performance',`${avg}% · ${tests.length} tests`,35],['Spaced revision',`${Math.round(rev*100)}% of studied topics`,20],['Consistency',`${days} active days`,20]].map(x=>`<div class="weight-item"><span>${x[0]} · ${x[2]}%</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="modal-actions"><button class="primary-button" data-action="close-modal">Got it</button></div>`)}
