function createSubject(){const name=$('#new-subject-name')?.value.trim(),raw=$('#new-subject-topics')?.value||'',topics=raw.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20);if(!name)return toast('Enter a subject name first.');if(state.subjects.some(s=>s.name.toLowerCase()===name.toLowerCase()))return toast('A subject with that name already exists.');const id=`custom-${crypto.randomUUID?.()||Date.now()}`,symbols=['✦','◇','✿','⌘'],s={id,name,icon:symbols[state.subjects.length%symbols.length],color:'blue',topics:topics.map((x,i)=>({id:`${id}-t${i}`,name:x,completedAt:null}))};state.subjects.push(s);save();closeModal();render();toast('Subject added to your quest!')}
function saveGoal(){const n=Number($('#goal-minutes')?.value);if(!Number.isFinite(n)||n<15||n>720)return toast('Choose a goal between 15 and 720 minutes.');state.targetMinutes=Math.round(n/15)*15;save();render();toast('Daily goal saved.')}
function exportData(){const backup={...state,activeTimer:null,exportedAt:new Date().toISOString()};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`study-quest-backup-${key()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded.')}
function importData(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(data.version!==1||!Array.isArray(data.subjects)||!Array.isArray(data.sessions)||!Array.isArray(data.quizzes))throw Error('This file is not a Study Quest backup.');if(!confirm('Replace all current progress with this backup?'))return;state={...fresh(),...data,activeTimer:null};state.xp=Math.max(0,Number(state.xp)||0);state.targetMinutes=Math.max(15,Math.min(720,Number(state.targetMinutes)||120));save();setView('dashboard');toast('Backup restored.')}catch(e){toast(e.message||'Could not read that backup.')}};reader.readAsText(file)}
function resetData(){if(!confirm('Delete all Study Quest data on this device? This cannot be undone.'))return;if(!confirm('Last check: permanently reset subjects, study logs, scores, and XP?'))return;localStorage.removeItem(KEY);state=fresh();save();setView('dashboard');toast('Fresh start ready.')}
