49:function render(){const f={dashboard:dashboard,subjects:subjects,revisions:revisions,analytics:analytics,challenges:challenges,boss:boss,competition:records,settings:settings};$('#view-container').innerHTML=(f[view]||dashboard)();bind();chrome()}
50:function header(title,desc,action=''){return `<div class="view-heading"><div><div class="eyebrow">STUDY QUEST / ${esc(title).toUpperCase()}</div><h1 class="page-title">${esc(title)}</h1><p class="subtitle">${desc}</p></div>${action}</div>`}
51:function stat(title,value,meta,icon,color,good=false){return `<article class="stat-card"><div class="stat-top">${title}<span class="stat-icon icon-${color}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-meta ${good?'positive':''}">${meta}</div></article>`}
52:function dashboard(){const total=sessionMins(),today=sessionMins(todaySessions()),week=days7(),due=dueList().filter(x=>x.overdue),ready=[...state.subjects].sort((a,b)=>readiness(b)-readiness(a)),ms=missions(),next=ready[0],active=state.activeTimer;return `${header('Your learning, in focus.','A little progress each day builds lasting confidence.',`<button class="primary-button" data-action="start-session"><span class="button-icon">▶</span>${active?'Session in progress':'Start a study session'}</button>`)}<div class="stats-grid">${stat('TOTAL STUDY TIME',minsText(total),`${today?minsText(today)+' today':'Start a session to begin'}`,'◷','lav')}${stat('CURRENT STREAK',`${streak()} days`,streak()?'Keep the rhythm going':'One session starts your streak','✦','peach',streak()>0)}${stat('QUEST POINTS',state.xp.toLocaleString(),`Level ${1+Math.floor(state.xp/250)} explorer`,'⬡','mint')}${stat('REVISION DUE',due.length, due.length?'Small review, big retention':'You are all caught up','↻','blue',!due.length)}</div><div class="dashboard-grid"><section class="panel focus-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR WEEK AT A GLANCE</span><h2>Study rhythm</h2></div><span class="soft-tag">${minsText(week.reduce((a,x)=>a+x.m,0))} this week</span></div><div class="week-chart">${week.map(x=>`<div class="chart-day"><div class="chart-track"><div class="chart-bar" style="height:${Math.max(4,Math.min(100,x.m/Math.max(30,state.targetMinutes/60)*100))}%" title="${Math.round(x.m)} minutes"></div></div><span>${x.label}</span></div>`).join('')}</div><div class="chart-legend"><i></i> Study time <span>Daily goal: ${minsText(state.targetMinutes)}</span></div></section><section class="panel focus-panel"><div class="panel-heading"><div><span class="eyebrow">DAILY QUESTS</span><h2>Three small wins</h2></div><button class="text-button" data-nav="challenges">View all →</button></div><div class="mission-list">${ms.map(m=>`<div class="mission-row"><span class="mission-check ${m.done?'done':''}">${m.done?'✓':'○'}</span><div><strong>${m.title}</strong><small>${m.detail}</small></div><span class="xp-pill">+${m.xp} XP</span></div>`).join('')}</div></section></div><section class="page-section"><div class="section-heading"><div><span class="eyebrow">SUBJECT READINESS</span><h2>Where you stand</h2></div><button class="text-button" data-nav="subjects">All subjects →</button></div><div class="readiness-list">${ready.map(s=>`<div class="readiness-row"><span>${esc(s.icon)} ${esc(s.name)}</span><div class="readiness-track"><i style="width:${readiness(s)}%"></i></div><strong>${readiness(s)}%</strong></div>`).join('')}</div></section><div class="dashboard-grid bottom-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SMART REVIEW</span><h2>${due.length?`${due.length} topic${due.length===1?'':'s'} ready to revisit`:'Build lasting memory'}</h2></div><span class="panel-emoji">↻</span></div><p class="panel-copy">${due.length?'Short spaced-repetition tests help move knowledge into long-term memory.':'Complete a topic, then we’ll schedule a quick review for tomorrow.'}</p><button class="secondary-button" data-nav="revisions">Open revision queue</button></section><section class="panel boss-teaser"><div class="panel-heading"><div><span class="eyebrow">WEEKLY MILESTONE</span><h2>Boss battle</h2></div><span class="panel-emoji">♜</span></div><p class="panel-copy">${Date.now()>=bossAt()?'Your weekly mixed-subject challenge is ready.':'Next battle '+fmtDate(bossAt())}</p><button class="secondary-button" data-nav="boss">${Date.now()>=bossAt()?'Enter the arena':'See battle details'}</button></section></div>`}
53:function subjects(){return `${header('My subjects','Track your curriculum, celebrate completed topics, and see exam readiness.','<button class="primary-button" data-action="add-subject">＋ Add subject</button>')}<div class="subject-grid">${state.subjects.map(s=>{const done=s.topics.filter(t=>t.completedAt).length,p=readiness(s);return `<article class="panel subject-card"><div class="subject-card-head"><span class="subject-symbol icon-${esc(s.color)}">${esc(s.icon)}</span><div><h3>${esc(s.name)}</h3><small>${done} of ${s.topics.length} topics studied</small></div><span class="subject-score">${p}%</span></div><div class="progress-line"><i style="width:${s.topics.length?done/s.topics.length*100:0}%"></i></div><div class="subject-card-foot"><span>Content coverage</span><span>${status(p)}</span></div><div class="topic-list">${s.topics.map(t=>`<div class="topic-item"><span class="topic-status ${t.completedAt?'complete':''}">${t.completedAt?'✓':''}</span><span class="topic-name">${esc(t.name)}</span>${t.completedAt?`<button class="soft-button" data-action="topic-test" data-topic="${esc(t.id)}">Practice</button>`:`<button class="secondary-button" data-action="complete-topic" data-topic="${esc(t.id)}">Study topic</button>`}</div>`).join('')||'<div class="topic-empty">No topics yet. Add a topic to get started.</div>'}</div><div class="subject-card-actions"><button class="soft-button" data-action="subject-quiz" data-subject="${esc(s.id)}" ${!s.topics.some(t=>t.completedAt)?'disabled':''}>Take a test</button><button class="text-button" data-action="readiness" data-subject="${esc(s.id)}">Readiness details</button></div></article>`}).join('')}</div>`}
54:function revisions(){const items=dueList(),due=items.filter(x=>x.overdue);return `${header('Revision queue','Spaced practice gives your learning room to stick.')}<div class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR RETENTION PLAN</span><h2>${due.length?`${due.length} review${due.length===1?'':'s'} due now`:'Nothing due today'}</h2></div><span class="soft-tag">${items.length} scheduled</span></div><p class="panel-copy">Reviews are scheduled 1, 3, 7, 15, and 30 days after you complete a topic. Each test is short and earns XP only when submitted.</p>${items.length?`<div class="retention-list">${items.map(x=>`<div class="retention-item"><div class="retention-date"><strong>${x.overdue?'NOW':fmtDate(x.due)}</strong><small>STEP ${x.stage}/5</small></div><div class="retention-main"><strong>${esc(x.s.name)} · ${esc(x.t.name)}</strong><small>${x.overdue?'Ready for a quick recall check':`Due ${fmtDate(x.due)}`}</small></div><button class="primary-button" data-action="revision-test" data-topic="${esc(x.t.id)}" ${!x.overdue?'disabled':''}>${x.overdue?'Start review':'Coming up'}</button></div>`).join('')}</div>`:'<div class="empty-state"><span>✦</span><h3>Great work staying current</h3><p>Complete a subject topic to start your revision schedule.</p><button class="secondary-button" data-nav="subjects">Browse subjects</button></div>'}</div>`}
55:function analytics(){const week=days7(),max=Math.max(1,...week.map(x=>x.m)),all=state.quizzes.filter(q=>!q.boss),avg=all.length?Math.round(all.reduce((a,x)=>a+x.percent,0)/all.length):0,topics=state.subjects.flatMap(s=>s.topics.map(t=>({s,t,qs:state.quizzes.filter(q=>q.topicId===t.id&&!q.boss)}))).filter(x=>x.qs.length),weak=[...topics].sort((a,b)=>a.qs.reduce((p,q)=>p+q.percent,0)/a.qs.length-b.qs.reduce((p,q)=>p+q.percent,0)/b.qs.length).slice(0,3);return `${header('Your progress, made visible.','Use real session and test results to guide your next study step.')}<div class="stats-grid">${stat('RECORDED STUDY TIME',minsText(sessionMins()),`${state.sessions.length} completed sessions`,'◷','lav')}${stat('TEST ACCURACY',`${avg}%`,`${all.length} submitted tests`,'✓','mint')}${stat('TOPICS COMPLETED',state.subjects.reduce((a,s)=>a+s.topics.filter(t=>t.completedAt).length,0),'Across all subjects','▤','peach')}${stat('CURRENT STREAK',`${streak()} days`,'Based on completed study sessions','✦','blue')}</div><div class="analytics-grid"><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">LAST 7 DAYS</span><h2>Time invested</h2></div><span class="soft-tag">${minsText(week.reduce((a,x)=>a+x.m,0))}</span></div><div class="bar-chart">${week.map(x=>`<div class="bar-column"><strong>${x.m?Math.round(x.m)+'m':''}</strong><div class="bar-track"><i style="height:${x.m/max*100}%"></i></div><small>${x.label}</small></div>`).join('')}</div></section><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">NEXT BEST STEPS</span><h2>Focus recommendations</h2></div><span class="panel-emoji">✧</span></div>${weak.length?`<div class="recommendation-list">${weak.map(x=>`<div class="recommendation"><strong>${esc(x.s.name)} · ${esc(x.t.name)}</strong><span>Average ${Math.round(x.qs.reduce((a,q)=>a+q.percent,0)/x.qs.length)}% — revisit the concept, then test again.</span><button class="text-button" data-action="topic-test" data-topic="${esc(x.t.id)}">Practice →</button></div>`).join('')}</div>`:'<p class="panel-copy">Submit a few topic tests and we’ll identify where targeted practice could help most.</p>'}</section></div><section class="page-section"><div class="section-heading"><div><span class="eyebrow">SUBJECT BY SUBJECT</span><h2>Exam readiness breakdown</h2></div></div><div class="panel wide-panel readiness-detail-grid">${state.subjects.map(s=>`<div class="weight-item"><span>${esc(s.name)}</span><strong>${readiness(s)}% · ${status(readiness(s))}</strong><div class="progress-line"><i style="width:${readiness(s)}%"></i></div></div>`).join('')}</div></section>`}
56:function challenges(){const ms=missions(),done=ms.filter(x=>x.done).length;return `${header('Daily challenges','Three achievable quests reward consistency, not app opens.')}<div class="challenge-layout"><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">TODAY’S QUESTS</span><h2>${done}/3 complete</h2></div><span class="soft-tag">${done===3?'Bonus claimed or ready':'60 XP + 50 bonus'}</span></div><div class="challenge-list">${ms.map((m,i)=>`<article class="challenge-card"><span class="challenge-number">0${i+1}</span><div class="challenge-content"><h3>${m.title}</h3><p>${m.detail}</p></div><span class="xp-pill">+${m.xp} XP</span><span class="mission-check ${m.done?'done':''}">${m.done?'✓':'○'}</span></article>`).join('')}</div>${done===3?'<div class="success-banner">✦ Daily bonus earned! +50 XP</div>':'<p class="panel-copy">Complete all three to earn a one-time 50 XP bonus. Opening the app alone never grants XP.</p>'}</section><aside class="panel challenge-side"><span class="eyebrow">QUEST LOG</span><h2>Consistency wins</h2><p class="panel-copy">Rewards are recorded once, after a real session or submitted test. Each daily bonus can be claimed once.</p><div class="quest-progress"><div class="progress-line"><i style="width:${done/3*100}%"></i></div><small>${done} of 3 quests complete</small></div></aside></div>`}
57:function boss(){const next=bossAt(),ready=Date.now()>=next,remaining=Math.max(0,Math.ceil((next-Date.now())/DAY)),last=state.bossBattles.at(-1),questions=state.subjects.flatMap(s=>allQs(s.id,true));return `${header('Weekly boss battle','A mixed-subject challenge tests the knowledge you have actually covered.',ready?'<button class="primary-button" data-action="start-boss" '+(questions.length<5?'disabled':'')+'>♜ Enter the arena</button>':'')}<div class="challenge-layout"><section class="panel boss-hero"><span class="boss-mark">♜</span><span class="eyebrow">THE WEEKLY GAUNTLET</span><h2>${ready?'The arena is open':`Returns in ${remaining} day${remaining===1?'':'s'}`}</h2><p class="panel-copy">${questions.length<5?'Complete at least five curriculum questions across studied topics to unlock a fair battle.':ready?'Answer 10 mixed questions drawn from topics you have completed. A score of 70% earns the champion reward.':`You have ${questions.length} available questions from completed topics. Keep practicing before the next battle.`}</p><div class="boss-rewards"><span>10 mixed questions</span><span>+100 XP at 70%+</span><span>Once per week</span></div>${ready&&questions.length>=5?'<button class="primary-button" data-action="start-boss">Start battle</button>':''}</section><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">BATTLE RECORD</span><h2>Past encounters</h2></div><span class="soft-tag">${state.bossBattles.length} battles</span></div>${state.bossBattles.length?`<div class="record-list">${state.bossBattles.slice().reverse().map(b=>`<div class="record-row"><span class="record-icon">${b.won?'♛':'♜'}</span><div><strong>${b.won?'Victory':'Challenge complete'} · ${b.percent}%</strong><small>${fmtDate(b.endedAt)} · ${b.correct}/${b.count} correct</small></div><span class="xp-pill">+${b.xp} XP</span></div>`).join('')}</div>`:'<div class="empty-state"><span>♜</span><h3>Your story starts here</h3><p>Battle results will appear after you complete a weekly challenge.</p></div>'}${last?`<p class="panel-copy">Last result: ${last.won?'champion!':'keep training'} · ${fmtDate(last.endedAt)}</p>`:''}</section></div>`}
58:function records(){const best=state.quizzes.length?Math.max(...state.quizzes.map(q=>q.percent)):0,improved=(()=>{let b=null;for(const s of state.subjects){const qs=state.quizzes.filter(q=>q.subjectId===s.id&&!q.boss&&!q.revision).sort((a,c)=>a.endedAt-c.endedAt);if(qs.length>1){const d=qs.at(-1).percent-qs[0].percent;if(!b||d>b.diff)b={name:s.name,diff:d}}}return b})();const daily={};for(const x of state.sessions)daily[key(new Date(x.endedAt))]=(daily[key(new Date(x.endedAt))]||0)+x.durationSec/3600;return `${header('Personal records','Milestones calculated from your recorded learning activity.')}<div class="record-grid">${record('Longest streak',`${longestStreak()} days`,'Consecutive days with a completed study session','✦')}${record('Best test score',`${best}%`,'Highest submitted quiz result','◎')}${record('Most focused day',`${Math.round(Math.max(0,...Object.values(daily))*60)} min`,'Most study time recorded in one day','◷')}${record('Best weekly XP',`${highestWeeklyXp()} XP`,'Earned from sessions and submitted tests','⬡')}${record('Biggest improvement',improved?`${improved.diff>0?'+':''}${improved.diff}%`:'—',improved?`${improved.name} · first to latest test`:'Complete more topic tests to reveal a trend','↗')}${record('Completed topics',state.subjects.reduce((a,s)=>a+s.topics.filter(t=>t.completedAt).length,0),'Topics finished across your subjects','✓')}</div><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>Your learning log</h2></div></div>${activity().length?`<div class="record-list">${activity().slice(0,8).map(x=>`<div class="record-row"><span class="record-icon">${x.icon}</span><div><strong>${esc(x.title)}</strong><small>${fmtDate(x.time)} · ${esc(x.detail)}</small></div><span class="xp-pill">+${x.xp} XP</span></div>`).join('')}</div>`:'<div class="empty-state"><span>✦</span><h3>Firsts to come</h3><p>Finish a session or submit a test to start your personal record book.</p></div>'}</section>`}
59:function record(title,value,detail,icon){return `<article class="panel record-card"><span class="record-icon">${icon}</span><span class="eyebrow">${title.toUpperCase()}</span><strong>${value}</strong><small>${detail}</small></article>`}
60:function activity(){return [...state.sessions.map(x=>({time:x.endedAt,title:'Study session',detail:`${minsText(x.durationSec/60)} · ${x.subjectName}`,xp:x.xp,icon:'◷'})),...state.quizzes.map(x=>({time:x.endedAt,title:x.boss?'Boss battle':x.revision?'Revision test':'Topic test',detail:`${x.percent}% · ${x.subjectName}`,xp:x.xp,icon:x.boss?'♜':'✓'}))].sort((a,b)=>b.time-a.time)}
61:function longestStreak(){const ds=[...new Set(state.sessions.map(x=>key(new Date(x.endedAt))))].sort();let best=0,n=0,last=null;for(const k of ds){const d=new Date(`${k}T00:00:00`);n=last&&d-last===DAY?n+1:1;best=Math.max(best,n);last=d}return best}
62:function highestWeeklyXp(){const map={};for(const x of [...state.sessions,...state.quizzes]){const d=new Date(x.endedAt),wk=`${d.getFullYear()}-${Math.floor((Number(d)-new Date(d.getFullYear(),0,1))/DAY/7)}`;map[wk]=(map[wk]||0)+(x.xp||0)}return Math.max(0,...Object.values(map))}
63:function reminders(){const out=[],due=dueList().filter(x=>x.overdue);if(due.length)out.push({title:`${due.length} revision${due.length===1?'':'s'} due`,detail:'A short recall check can strengthen retention.',nav:'revisions'});if(!todaySessions().length)out.push({title:'Your daily streak is waiting',detail:'A focused study session starts today’s progress.',nav:'dashboard'});const goal=state.targetMinutes-sessionMins(todaySessions());if(goal>0&&todaySessions().length)out.push({title:`${minsText(goal)} to your daily goal`,detail:'You are building a steady study rhythm.',nav:'dashboard'});return out}
64:function settings(){return `${header('Settings & data','Your progress stays in this browser. Export a backup whenever you like.')}<div class="settings-grid"><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR ROUTINE</span><h2>Study goal & reminders</h2></div></div><label class="field-label" for="goal-minutes">Daily study goal (minutes)</label><div class="inline-form"><input id="goal-minutes" type="number" min="15" max="720" step="15" value="${state.targetMinutes}"><button class="primary-button" data-action="save-goal">Save goal</button></div><p class="panel-copy">The goal tracks completed session time only; open tabs and breaks do not count.</p><div class="setting-row"><div><strong>Smart reminders</strong><small>Show gentle in-app reminders for due reviews and today’s goal.</small></div><button class="secondary-button" data-action="reminder-settings">${state.remindersEnabled===false?'Enable reminders':'Reminders on'}</button></div></section><section class="panel wide-panel"><div class="panel-heading"><div><span class="eyebrow">PORTABLE PROGRESS</span><h2>Backup & restore</h2></div></div><p class="panel-copy">Export your subjects, session log, test history, XP, and preferences to a JSON file.</p><div class="button-row"><button class="secondary-button" data-action="export">Download backup</button><button class="secondary-button" data-action="import">Import backup</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></section><section class="panel wide-panel danger-panel"><div class="panel-heading"><div><span class="eyebrow">START FRESH</span><h2>Reset your learning data</h2></div></div><p class="panel-copy">This permanently removes local sessions, scores, subjects, and earned XP. Export a backup first if you want to keep them.</p><button class="danger-button" data-action="reset">Reset all progress</button></section></div>`}
65:function startSessionDialog(){if(state.activeTimer){stopSession();return}openModal(`<div class="modal-head"><div><span class="eyebrow">FOCUS SESSION</span><h2>What are you studying?</h2></div><button class="modal-close" data-action="close-modal">×</button></div><p class="panel-copy">Your timer begins only when you confirm. Complete at least 5 focused minutes to record a session and earn XP.</p><label class="field-label" for="session-subject">Subject</label><select id="session-subject">${state.subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" data-action="confirm-session">Start focus timer</button></div>`)}
66:function startSession(subjectId){if(state.activeTimer)return toast('A focus timer is already running.');const s=state.subjects.find(x=>x.id===subjectId);if(!s)return;state.activeTimer={subjectId:s.id,subjectName:s.name,startedAt:Date.now()};save();closeModal();render();timerTick=setInterval(()=>{if(!state.activeTimer){clearInterval(timerTick);return}const el=$('#session-clock');if(el)el.textContent=elapsedText(Date.now()-state.activeTimer.startedAt)},1000);toast('Focus timer started. You’ve got this!')}
67:function elapsedText(ms){const n=Math.floor(ms/1000);return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
68:function stopSession(){const t=state.activeTimer;if(!t)return toast('No session is running.');const seconds=Math.floor((Date.now()-t.startedAt)/1000);if(seconds<300){state.activeTimer=null;save();clearInterval(timerTick);render();toast('Session was under 5 minutes, so it was not recorded.');return}const durationSec=Math.min(seconds,12*3600),xp=Math.min(60,Math.floor(durationSec/300)*5),now=Date.now();state.sessions.push({id:crypto.randomUUID?.()||String(now),subjectId:t.subjectId,subjectName:t.subjectName,startedAt:t.startedAt,endedAt:now,durationSec,xp});state.xp+=xp;state.activeTimer=null;save();clearInterval(timerTick);checkMissions();render();toast(`Session saved · +${xp} XP`)}
69:function completeTopic(id){const x=findTopic(id);if(!x)return;if(x.t.completedAt)return toast('This topic is already completed.');x.t.completedAt=Date.now();save();render();toast('Topic completed. Spaced reviews are now scheduled!')}
70:function beginQuiz(type,subjectId,topicId){if(quiz)return toast('Finish or close the current test first.');let pool=[];if(topicId)pool=allQs(findTopic(topicId)?.s.id||'',false).filter(q=>q.topicId===topicId);else if(subjectId)pool=allQs(subjectId,true);else pool=state.subjects.flatMap(s=>allQs(s.id,true));if(!pool.length)return toast('Study a topic first to unlock its questions.');if(type==='revision'&&topicId)pool=pool.filter(q=>q.topicId===topicId);const n=type==='boss'?10:Math.min(10,pool.length);if(type==='boss'&&pool.length<10)return toast('Complete more topics to unlock 10 unique boss questions.');pool.sort(()=>Math.random()-.5);quiz={type,subjectId:subjectId||pool[0].subjectId,topicId,questions:pool.slice(0,n),answers:Array(n).fill(null),index:0,startedAt:Date.now()};renderQuestion()}
71:function renderQuestion(){if(!quiz)return;const q=quiz.questions[quiz.index];openModal(`<div class="quiz-top"><div><span class="eyebrow">${quiz.type==='boss'?'WEEKLY BOSS':quiz.type==='revision'?'SPACED REVISION':'KNOWLEDGE CHECK'}</span><h2>${esc(q.subject)} · ${esc(q.topic)}</h2></div><button class="modal-close" data-action="quit-quiz">×</button></div><div class="quiz-progress"><span>Question ${quiz.index+1} of ${quiz.questions.length}</span><div class="progress-line"><i style="width:${(quiz.index+1)/quiz.questions.length*100}%"></i></div></div><h3 class="quiz-prompt">${esc(q.text)}</h3><div class="answer-list">${q.options.map((x,i)=>`<button class="answer-option ${quiz.answers[quiz.index]===i?'selected':''}" data-action="answer" data-answer="${i}"><span class="answer-letter">${String.fromCharCode(65+i)}</span>${esc(x)}</button>`).join('')}</div><div class="modal-actions"><span class="quiz-note">Answers are reviewed after submission.</span><button class="primary-button" data-action="quiz-next" ${quiz.answers[quiz.index]===null?'disabled':''}>${quiz.index===quiz.questions.length-1?'Submit test':'Next question →'}</button></div>`)}
72:function quizNext(){if(!quiz||quiz.answers[quiz.index]===null)return;if(quiz.index<quiz.questions.length-1){quiz.index++;renderQuestion();return}finishQuiz()}
